    out.push_str(
        "\nstatic PTN_UNUSED void ptn_initialize_declared_exception_object(PtnRuntime *runtime, PtnValue object, size_t argc, const PtnValue *args, size_t line) {\n",
    );
    out.push_str("    PtnValue resolved = ptn_value_deref(object);\n");
    out.push_str("    const char *declaring_class = \"Exception\";\n");
    out.push_str("    if (resolved.type == PTN_OBJECT) {\n");
    out.push_str("        declaring_class = ptn_exception_constructor_declaring_class(runtime, resolved.as.object->class_name);\n");
    out.push_str("    }\n");
    out.push_str("    if (argc > ptn_exception_constructor_max_args(declaring_class)) {\n");
    out.push_str("        ptn_throw_exception(runtime, \"ArgumentCountError\", \"Exception constructor expects at most 3 arguments\");\n");
    out.push_str("        return;\n");
    out.push_str("    }\n");
    out.push_str("    PtnStringOperand message_payload = ptn_exception_constructor_message(runtime, declaring_class, argc, args, line);\n");
    out.push_str("    PtnValue message = ptn_owned_string_len(message_payload.owned, message_payload.len);\n");
    out.push_str("    PtnValue code = argc >= 2 ? ptn_int(ptn_value_deref(args[1]).type == PTN_INT ? ptn_value_deref(args[1]).as.integer : 0) : ptn_int(0);\n");
    out.push_str("    size_t previous_index = ptn_exception_name_equal(declaring_class, \"ErrorException\") ? 5 : 2;\n");
    out.push_str(
        "    PtnValue previous = argc > previous_index ? ptn_value_clone_deref(args[previous_index]) : ptn_null();\n",
    );
    out.push_str("    PtnValue assigned = ptn_object_declare_property(runtime, object, \"message\", declaring_class, PTN_PROPERTY_PROTECTED, PTN_PROPERTY_PROTECTED, 0, PTN_PROPERTY_TYPE_NONE, NULL, NULL, 0, 1, message, line);\n");
    out.push_str("    ptn_value_destroy(&assigned);\n");
    out.push_str("    assigned = ptn_object_declare_property(runtime, object, \"code\", declaring_class, PTN_PROPERTY_PROTECTED, PTN_PROPERTY_PROTECTED, 0, PTN_PROPERTY_TYPE_NONE, NULL, NULL, 0, 1, code, line);\n");
    out.push_str("    ptn_value_destroy(&assigned);\n");
    out.push_str("    PtnValue file = ptn_owned_string(ptn_duplicate_string(runtime->source_path != NULL ? runtime->source_path : \"\"));\n");
    out.push_str(
        "    if (ptn_exception_name_equal(declaring_class, \"ErrorException\") && argc >= 4) {\n",
    );
    out.push_str("        PtnValue file_arg = ptn_value_deref(args[3]);\n");
    out.push_str("        if (file_arg.type == PTN_STRING) {\n");
    out.push_str("            ptn_value_destroy(&file);\n");
    out.push_str("            file = ptn_owned_string_len(ptn_duplicate_string_len((const char *)file_arg.as.string.data, file_arg.as.string.len), file_arg.as.string.len);\n");
    out.push_str("        }\n");
    out.push_str("    }\n");
    out.push_str("    assigned = ptn_object_declare_property(runtime, object, \"file\", declaring_class, PTN_PROPERTY_PROTECTED, PTN_PROPERTY_PROTECTED, 0, PTN_PROPERTY_TYPE_NONE, NULL, NULL, 0, 1, file, line);\n");
    out.push_str("    ptn_value_destroy(&assigned);\n");
    out.push_str("    ptn_value_destroy(&file);\n");
    out.push_str("    int64_t exception_line = (int64_t)line;\n");
    out.push_str(
        "    if (ptn_exception_name_equal(declaring_class, \"ErrorException\") && argc >= 5) {\n",
    );
    out.push_str("        PtnValue line_arg = ptn_value_deref(args[4]);\n");
    out.push_str("        if (line_arg.type == PTN_INT) {\n");
    out.push_str("            exception_line = line_arg.as.integer;\n");
    out.push_str("        } else if (line_arg.type == PTN_BOOL) {\n");
    out.push_str("            exception_line = line_arg.as.boolean ? 1 : 0;\n");
    out.push_str("        } else if (line_arg.type == PTN_FLOAT) {\n");
    out.push_str("            exception_line = (int64_t)line_arg.as.floating;\n");
    out.push_str("        }\n");
    out.push_str("    }\n");
    out.push_str("    assigned = ptn_object_declare_property(runtime, object, \"line\", declaring_class, PTN_PROPERTY_PROTECTED, PTN_PROPERTY_PROTECTED, 0, PTN_PROPERTY_TYPE_NONE, NULL, NULL, 0, 1, ptn_int(exception_line), line);\n");
    out.push_str("    ptn_value_destroy(&assigned);\n");
    out.push_str("    assigned = ptn_object_declare_property(runtime, object, \"previous\", declaring_class, PTN_PROPERTY_PROTECTED, PTN_PROPERTY_PROTECTED, 0, PTN_PROPERTY_TYPE_NONE, NULL, NULL, 0, 1, previous, line);\n");
    out.push_str("    ptn_value_destroy(&assigned);\n");
    out.push_str("    if (ptn_exception_name_equal(declaring_class, \"ErrorException\")) {\n");
    out.push_str("        PtnValue severity = argc >= 3 ? ptn_int(ptn_value_deref(args[2]).type == PTN_INT ? ptn_value_deref(args[2]).as.integer : PTN_E_ERROR) : ptn_int(PTN_E_ERROR);\n");
    out.push_str("        assigned = ptn_object_declare_property(runtime, object, \"severity\", declaring_class, PTN_PROPERTY_PROTECTED, PTN_PROPERTY_PROTECTED, 0, PTN_PROPERTY_TYPE_NONE, NULL, NULL, 0, 1, severity, line);\n");
    out.push_str("        ptn_value_destroy(&assigned);\n");
    out.push_str("        ptn_value_destroy(&severity);\n");
    out.push_str("    }\n");
    out.push_str("    if (resolved.type == PTN_EXCEPTION && ptn_exception_name_equal(declaring_class, \"Uri\\\\WhatWg\\\\InvalidUrlException\")) {\n");
