fn emit_modeled_internal_class_vars(out: &mut String, indent: &str, class_name: &str) {
    if class_name == "DimensionHandlersNoArrayAccess" {
        for (property_name, default_expr, _) in modeled_internal_public_properties(class_name) {
            out.push_str(indent);
            out.push_str("ptn_array_set_entry(result.as.array, ptn_array_string_key(\"");
            out.push_str(property_name);
            out.push_str("\"), ");
            out.push_str(default_expr);
            out.push_str(");\n");
        }
        return;
    }
    let null_property_names: &[&str] = if matches!(
        class_name,
        "ReflectionClass" | "ReflectionEnum" | "ReflectionObject"
    ) {
        &["name"]
    } else if matches!(
        class_name,
        "ReflectionClassConstant"
            | "ReflectionEnumBackedCase"
            | "ReflectionEnumUnitCase"
            | "ReflectionMethod"
            | "ReflectionProperty"
    ) {
        &["name", "class"]
    } else if matches!(
        class_name,
        "ReflectionFunction" | "ReflectionFunctionAbstract" | "ReflectionParameter"
    ) {
        &["name"]
    } else {
        &[]
    };
    for property_name in null_property_names {
        out.push_str(indent);
        out.push_str("ptn_array_set_entry(result.as.array, ptn_array_string_key(\"");
        out.push_str(property_name);
        out.push_str("\"), ptn_null());\n");
    }
}

fn modeled_internal_public_properties(
    class_name: &str,
) -> &'static [(&'static str, &'static str, bool)] {
    if class_name == "DimensionHandlersNoArrayAccess" {
        &[
            ("read", "ptn_bool(0)", true),
            ("write", "ptn_bool(0)", true),
            ("has", "ptn_bool(0)", true),
            ("unset", "ptn_bool(0)", true),
            ("readType", "ptn_null()", false),
            ("hasOffset", "ptn_bool(0)", true),
            ("checkEmpty", "ptn_null()", false),
            ("offset", "ptn_null()", false),
        ]
    } else {
        &[]
    }
}

fn emit_modeled_internal_property_exists(out: &mut String, indent: &str, class_name: &str) {
    for (property_name, _, _) in modeled_internal_public_properties(class_name) {
        out.push_str(indent);
        out.push_str("if (strcmp(property_name, \"");
        out.push_str(property_name);
        out.push_str("\") == 0) {\n");
        out.push_str(indent);
        out.push_str("    return 1;\n");
        out.push_str(indent);
        out.push_str("}\n");
    }
}

fn emit_modeled_internal_property_metadata(out: &mut String, indent: &str, class_name: &str) {
    for (property_name, _, _) in modeled_internal_public_properties(class_name) {
        out.push_str(indent);
        out.push_str("if (strcmp(property_name, \"");
        out.push_str(property_name);
        out.push_str("\") == 0) {\n");
        out.push_str(indent);
        out.push_str("    if (declaring_class_out != NULL) {\n");
        out.push_str(indent);
        out.push_str("        *declaring_class_out = \"");
        out.push_str(class_name);
        out.push_str("\";\n");
        out.push_str(indent);
        out.push_str("    }\n");
        out.push_str(indent);
        out.push_str("    if (visibility_out != NULL) {\n");
        out.push_str(indent);
        out.push_str("        *visibility_out = PTN_PROPERTY_PUBLIC;\n");
        out.push_str(indent);
        out.push_str("    }\n");
        out.push_str(indent);
        out.push_str("    if (set_visibility_out != NULL) {\n");
        out.push_str(indent);
        out.push_str("        *set_visibility_out = PTN_PROPERTY_PUBLIC;\n");
        out.push_str(indent);
        out.push_str("    }\n");
        out.push_str(indent);
        out.push_str("    if (is_static_out != NULL) {\n");
        out.push_str(indent);
        out.push_str("        *is_static_out = 0;\n");
        out.push_str(indent);
        out.push_str("    }\n");
        out.push_str(indent);
        out.push_str("    return 1;\n");
        out.push_str(indent);
        out.push_str("}\n");
    }
}

fn emit_modeled_internal_reflection_property_metadata(
    out: &mut String,
    indent: &str,
    class_name: &str,
) {
    for (property_name, _, has_default) in modeled_internal_public_properties(class_name) {
        out.push_str(indent);
        out.push_str("if (strcmp(property_name, \"");
        out.push_str(property_name);
        out.push_str("\") == 0) {\n");
        out.push_str(indent);
        out.push_str("    *declaring_class = \"");
        out.push_str(class_name);
        out.push_str("\";\n");
        out.push_str(indent);
        out.push_str("    *is_static = 0;\n");
        out.push_str(indent);
        out.push_str("    *visibility = PTN_PROPERTY_PUBLIC;\n");
        out.push_str(indent);
        out.push_str("    *has_default = ");
        out.push_str(if *has_default { "1" } else { "0" });
        out.push_str(";\n");
        out.push_str(indent);
        out.push_str("    *modifiers = 1;\n");
        out.push_str(indent);
        out.push_str("    return 1;\n");
        out.push_str(indent);
        out.push_str("}\n");
    }
}

fn emit_direct_modeled_internal_class_vars(out: &mut String) {
    let class_names = [
        "ReflectionClass",
        "ReflectionEnum",
        "ReflectionObject",
        "ReflectionClassConstant",
        "ReflectionEnumBackedCase",
        "ReflectionEnumUnitCase",
        "ReflectionMethod",
        "ReflectionProperty",
        "ReflectionFunction",
        "ReflectionFunctionAbstract",
        "ReflectionParameter",
        "DimensionHandlersNoArrayAccess",
    ];
    for class_name in class_names {
        out.push_str("    if (ptn_ascii_case_equal(class_name, \"");
        out.push_str(class_name);
        out.push_str("\")) {\n");
        emit_modeled_internal_class_vars(out, "        ", class_name);
        out.push_str("        return result;\n");
        out.push_str("    }\n");
    }
}

fn inherited_modeled_internal_class_name(
    class: &ClassDecl,
    classes: &[ClassDecl],
) -> Option<&'static str> {
    let mut parent_name = class.parent_name.as_deref();
    while let Some(name) = parent_name {
        if let Some(internal_name) = modeled_internal_class_name(name) {
            return Some(internal_name);
        }
        parent_name = class_by_name(classes, name).and_then(|parent| parent.parent_name.as_deref());
    }
    None
}

struct ReflectionTraitAliasEntry {
    alias: String,
    trait_name: String,
    method_name: String,
}

fn class_reflection_trait_alias_entries(
    class: &ClassDecl,
    traits: &[TraitDecl],
) -> Vec<ReflectionTraitAliasEntry> {
    let mut entries = Vec::new();
    let mut seen = HashSet::new();
    for trait_use in &class.trait_uses {
        for alias in &trait_use.aliases {
            let Some(trait_name) =
                reflection_trait_alias_trait_name(class, traits, trait_use, alias)
            else {
                continue;
            };
            let key = format!(
                "{}\0{}\0{}",
                alias.alias.to_ascii_lowercase(),
                trait_name.to_ascii_lowercase(),
                alias.method_name.to_ascii_lowercase()
            );
            if !seen.insert(key) {
                continue;
            }
            entries.push(ReflectionTraitAliasEntry {
                alias: alias.alias.clone(),
                trait_name,
                method_name: alias.method_name.clone(),
            });
        }
    }
    entries
}

fn reflection_trait_alias_trait_name(
    class: &ClassDecl,
    traits: &[TraitDecl],
    trait_use: &TraitUseDecl,
    alias: &crate::ir::TraitAliasDecl,
) -> Option<String> {
    if let Some(trait_name) = alias.trait_name.as_deref() {
        return Some(
            canonical_trait_name(traits, trait_name)
                .unwrap_or(trait_name)
                .to_string(),
        );
    }
    let mut matches = class.trait_uses.iter().filter_map(|candidate_use| {
        let trait_decl = traits
            .iter()
            .find(|candidate| candidate.name.eq_ignore_ascii_case(&candidate_use.name))?;
        trait_decl
            .methods
            .iter()
            .any(|method| method.name.eq_ignore_ascii_case(&alias.method_name))
            .then_some(trait_decl.name.as_str())
    });
    let first = matches.next()?;
    if matches.next().is_some() {
        return None;
    }
    if trait_use.name.eq_ignore_ascii_case(first) {
        return Some(first.to_string());
    }
    Some(first.to_string())
}

fn canonical_trait_name<'a>(traits: &'a [TraitDecl], name: &str) -> Option<&'a str> {
    traits
        .iter()
        .find(|trait_decl| trait_decl.name.eq_ignore_ascii_case(name))
        .map(|trait_decl| trait_decl.name.as_str())
}

fn class_magic_call_method<'a>(
    class: &'a ClassDecl,
    classes: &'a [ClassDecl],
) -> Option<&'a crate::ir::MethodDecl> {
    class_method_lookup_chain(class, classes)
        .into_iter()
        .find(|method| !method.is_static && method.name.eq_ignore_ascii_case("__call"))
        .map(|method| method.method)
}

fn class_magic_call_static_method<'a>(
    class: &'a ClassDecl,
    classes: &'a [ClassDecl],
) -> Option<&'a crate::ir::MethodDecl> {
    class_method_lookup_chain(class, classes)
        .into_iter()
        .find(|method| {
            method.visibility == PropertyVisibility::Public
                && method.is_static
                && method.name.eq_ignore_ascii_case("__callStatic")
        })
        .map(|method| method.method)
}

fn trait_magic_call_static_method(trait_decl: &TraitDecl) -> Option<&TraitMethodDecl> {
    trait_decl.methods.iter().find(|method| {
        method.visibility == PropertyVisibility::Public
            && method.is_static
            && method.name.eq_ignore_ascii_case("__callStatic")
    })
}

fn emit_scoped_instance_magic_call(
    out: &mut String,
    indent: &str,
    class_name: &str,
    method: &crate::ir::MethodDecl,
    function: &FunctionDecl,
    receiver_expr: &str,
    result_lhs: &str,
) {
    out.push_str(indent);
    out.push_str("PtnValue ptn_magic_args[2];\n");
    out.push_str(indent);
    out.push_str("ptn_magic_args[0] = ptn_owned_string(ptn_duplicate_string(method_name));\n");
    out.push_str(indent);
    out.push_str("ptn_magic_args[1] = ptn_array_from_literal_entries(0, NULL);\n");
    out.push_str(indent);
    out.push_str("for (size_t ptn_magic_arg_i = 0; ptn_magic_arg_i < argc; ptn_magic_arg_i++) {\n");
    out.push_str(indent);
    out.push_str("    if (ptn_magic_arg_i > (size_t)INT64_MAX) {\n");
    out.push_str(indent);
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str(indent);
    out.push_str("    }\n");
    out.push_str(indent);
    out.push_str("    const char *ptn_magic_arg_name = runtime->next_call_arg_names != NULL ? runtime->next_call_arg_names[ptn_magic_arg_i] : NULL;\n");
    out.push_str(indent);
    out.push_str("    PtnArrayKey ptn_magic_arg_key = ptn_magic_arg_name != NULL ? ptn_array_string_key(ptn_magic_arg_name) : ptn_array_int_key((int64_t)ptn_magic_arg_i);\n");
    out.push_str(indent);
    out.push_str("    PtnValue ptn_magic_arg_value = ptn_value_deep_clone(ptn_value_deref(args[ptn_magic_arg_i]));\n");
    out.push_str(indent);
    out.push_str("    ptn_array_set_entry(ptn_magic_args[1].as.array, ptn_magic_arg_key, ptn_magic_arg_value);\n");
    out.push_str(indent);
    out.push_str("}\n");
    emit_dynamic_method_deprecated_warning(
        out,
        indent,
        "&runtime->diagnostics",
        class_name,
        "method_name",
        function,
        "line",
    );
    emit_dynamic_method_no_discard_warning(
        out,
        indent,
        "&runtime->diagnostics",
        class_name,
        "method_name",
        function,
        "line",
    );
    out.push_str(indent);
    out.push_str(
        "const char *const *ptn_magic_previous_arg_names = runtime->next_call_arg_names;\n",
    );
    out.push_str(indent);
    out.push_str("runtime->next_call_arg_names = NULL;\n");
    out.push_str(indent);
    out.push_str(
        "const char *ptn_magic_previous_called_class = runtime->called_class_name_override;\n",
    );
    out.push_str(indent);
    out.push_str("runtime->called_class_name_override = effective_called_class;\n");
    out.push_str(indent);
    out.push_str(result_lhs);
    out.push_str(&user_function_c_name(method.function_index));
    out.push_str("(runtime, ");
    out.push_str(receiver_expr);
    out.push_str(", 2, ptn_magic_args, line);\n");
    out.push_str(indent);
    out.push_str("runtime->called_class_name_override = ptn_magic_previous_called_class;\n");
    out.push_str(indent);
    out.push_str("runtime->next_call_arg_names = ptn_magic_previous_arg_names;\n");
    out.push_str(indent);
    out.push_str("ptn_value_destroy(&ptn_magic_args[0]);\n");
    out.push_str(indent);
    out.push_str("ptn_value_destroy(&ptn_magic_args[1]);\n");
}

fn emit_scoped_instance_magic_call_from_receiver_slot(
    out: &mut String,
    indent: &str,
    target_class: &ClassDecl,
    classes: &[ClassDecl],
    functions: &[FunctionDecl],
    receiver_expr: &str,
    result_lhs: &str,
) -> bool {
    let Some(target_magic_method) = class_magic_call_method(target_class, classes) else {
        return false;
    };

    out.push_str(indent);
    out.push_str("if (resolved_receiver.type == PTN_OBJECT && ptn_runtime_declared_class_is_same_or_descendant(runtime, resolved_receiver.as.object->class_name, target_class_name)) {\n");
    for receiver_class in classes {
        let Some(receiver_magic_method) = class_magic_call_method(receiver_class, classes) else {
            continue;
        };
        let receiver_magic_function = &functions[receiver_magic_method.function_index];
        out.push_str(indent);
        out.push_str("    if (ptn_ascii_case_equal(resolved_receiver.as.object->class_name, \"");
        out.push_str(&c_string(&receiver_class.name));
        out.push_str("\")) {\n");
        emit_scoped_instance_magic_call(
            out,
            &format!("{indent}        "),
            &receiver_class.name,
            receiver_magic_method,
            receiver_magic_function,
            receiver_expr,
            result_lhs,
        );
        out.push_str(indent);
        out.push_str("        return 1;\n");
        out.push_str(indent);
        out.push_str("    }\n");
    }

    let target_magic_function = &functions[target_magic_method.function_index];
    emit_scoped_instance_magic_call(
        out,
        &format!("{indent}    "),
        &target_class.name,
        target_magic_method,
        target_magic_function,
        receiver_expr,
        result_lhs,
    );
    out.push_str(indent);
    out.push_str("    return 1;\n");
    out.push_str(indent);
    out.push_str("}\n");
    true
}

