fn emit_declaration_dependency_autoload(
    out: &mut String,
    indent: &str,
    class_name: &str,
    class_index: usize,
    resolved_name_temp: &str,
    source_path: &str,
    line: usize,
) {
    let frame_temp = format!(
        "ptn_dependency_autoload_frame_{}_{}",
        class_index, resolved_name_temp
    );
    out.push_str(indent);
    out.push_str("PtnTryFrame ");
    out.push_str(&frame_temp);
    out.push_str(";\n");
    out.push_str(indent);
    out.push_str("ptn_try_frame_push(&runtime, &");
    out.push_str(&frame_temp);
    out.push_str(");\n");
    out.push_str(indent);
    out.push_str("if (setjmp(");
    out.push_str(&frame_temp);
    out.push_str(".jump) == 0) {\n");
    out.push_str(indent);
    out.push_str("    ptn_runtime_autoload_class_with_call_frame(&runtime, ");
    out.push_str(resolved_name_temp);
    out.push_str(", ");
    out.push_str(&line.to_string());
    out.push_str(", 0, 1");
    out.push_str(");\n");
    out.push_str(indent);
    out.push_str("    ptn_try_frame_pop(&runtime, &");
    out.push_str(&frame_temp);
    out.push_str(");\n");
    out.push_str(indent);
    out.push_str("} else {\n");
    out.push_str(indent);
    out.push_str("    ptn_try_frame_pop(&runtime, &");
    out.push_str(&frame_temp);
    out.push_str(");\n");
    emit_declaration_dependency_exception_handling(
        out,
        &format!("{indent}    "),
        class_name,
        class_index,
        source_path,
        line,
    );
    out.push_str(indent);
    out.push_str("}\n");
}

