                || class_name.eq_ignore_ascii_case("RecursiveCallbackFilterIterator")
                || class_name.eq_ignore_ascii_case("RecursiveIteratorIterator")
                || class_name.eq_ignore_ascii_case("RecursiveRegexIterator")
                || class_name.eq_ignore_ascii_case("RecursiveArrayIterator")
                || class_name.eq_ignore_ascii_case("SplDoublyLinkedList")
                || class_name.eq_ignore_ascii_case("SplFixedArray")
                || class_name.eq_ignore_ascii_case("SplObjectStorage")
                || class_name.eq_ignore_ascii_case("SplHeap")
                || class_name.eq_ignore_ascii_case("SplMaxHeap")
                || class_name.eq_ignore_ascii_case("SplMinHeap")
                || class_name.eq_ignore_ascii_case("SplPriorityQueue")
                || class_name.eq_ignore_ascii_case("SplQueue")
                || class_name.eq_ignore_ascii_case("SplStack")
                || class_name.eq_ignore_ascii_case("SplFileInfo")
                || class_name.eq_ignore_ascii_case("SplFileObject")
                || class_name.eq_ignore_ascii_case("DateTime")
                || class_name.eq_ignore_ascii_case("DateTimeImmutable")
                || class_name.eq_ignore_ascii_case("DateInterval")
                || class_name.eq_ignore_ascii_case("IntlBreakIterator")
                || class_name.eq_ignore_ascii_case("IntlRuleBasedBreakIterator")
                || class_name.eq_ignore_ascii_case("IntlCodePointBreakIterator")
                || class_name.eq_ignore_ascii_case("IntlPartsIterator")
                || class_name.eq_ignore_ascii_case("IntlCalendar")
                || class_name.eq_ignore_ascii_case("IntlGregorianCalendar")
                || class_name.eq_ignore_ascii_case("IntlDateFormatter")
                || class_name.eq_ignore_ascii_case("IntlTimeZone")
                || class_name.eq_ignore_ascii_case("IntlIterator")
                || class_name.eq_ignore_ascii_case("MessageFormatter")
                || class_name.eq_ignore_ascii_case("IntlChar")
                || class_name.eq_ignore_ascii_case("IntlListFormatter")
                || class_name.eq_ignore_ascii_case("IntlDatePatternGenerator")
                || class_name.eq_ignore_ascii_case("Locale")
                || class_name.eq_ignore_ascii_case("Normalizer")
                || class_name.eq_ignore_ascii_case("NumberFormatter")
                || class_name.eq_ignore_ascii_case("IntlNumberRangeFormatter")
                || class_name.eq_ignore_ascii_case("Collator")
