fn internal_parameter_default_expr(default: InternalParameterDefault) -> ValueExpr {
    match default {
        InternalParameterDefault::Null => ValueExpr::Null,
        InternalParameterDefault::Int(value) => ValueExpr::Int(value),
        InternalParameterDefault::String(value) => ValueExpr::String(value.to_string()),
    }
}

fn bind_named_internal_call_arguments(
    name: &str,
    arguments: &[ValueExpr],
    argument_names: &[Option<String>],
) -> Option<std::result::Result<BoundInternalArguments, NamedArgumentBindingError>> {
    bind_named_internal_arguments(
        internal_named_call_parameters(name)?,
        arguments,
        argument_names,
    )
}

fn bind_named_internal_method_call_arguments(
    name: &str,
    arguments: &[ValueExpr],
    argument_names: &[Option<String>],
) -> Option<std::result::Result<BoundInternalArguments, NamedArgumentBindingError>> {
    static SOAP_FAULT_CONSTRUCT_PARAMETERS: [InternalParameterSpec; 6] = [
        InternalParameterSpec {
            name: "code",
            default: None,
        },
        InternalParameterSpec {
            name: "string",
            default: None,
        },
        InternalParameterSpec {
            name: "actor",
            default: Some(InternalParameterDefault::Null),
        },
        InternalParameterSpec {
            name: "details",
            default: Some(InternalParameterDefault::Null),
        },
        InternalParameterSpec {
            name: "name",
            default: Some(InternalParameterDefault::Null),
        },
        InternalParameterSpec {
            name: "headerFault",
            default: Some(InternalParameterDefault::Null),
        },
    ];
    let soap_fault_headerfault_named = name.eq_ignore_ascii_case("__construct")
        && argument_names
            .iter()
            .flatten()
            .any(|argument_name| argument_name == "headerFault");
    if soap_fault_headerfault_named {
        return bind_named_internal_arguments(
            &SOAP_FAULT_CONSTRUCT_PARAMETERS,
            arguments,
            argument_names,
        );
    }
    bind_named_internal_arguments(
        internal_named_method_call_parameters(name)?,
        arguments,
        argument_names,
    )
}

fn bind_named_internal_arguments(
    parameters: &[InternalParameterSpec],
    arguments: &[ValueExpr],
    argument_names: &[Option<String>],
) -> Option<std::result::Result<BoundInternalArguments, NamedArgumentBindingError>> {
    let mut slots = vec![None; parameters.len()];
    for (argument_index, (argument, argument_name)) in
        arguments.iter().zip(argument_names.iter()).enumerate()
    {
        let slot = if let Some(argument_name) = argument_name {
            let Some(parameter_index) = parameters
                .iter()
                .position(|parameter| parameter.name == argument_name)
            else {
                return Some(Err(NamedArgumentBindingError::Unknown(
                    argument_name.clone(),
                )));
            };
            parameter_index
        } else {
            argument_index
        };

        if slot >= slots.len() {
            return None;
        }
        if slots[slot].is_some() {
            return Some(Err(NamedArgumentBindingError::Duplicate(
                parameters[slot].name.to_string(),
            )));
        }
        slots[slot] = Some(argument.clone());
    }

    let Some(last_slot) = slots.iter().rposition(Option::is_some) else {
        return Some(Ok(BoundInternalArguments {
            arguments: Vec::new(),
            defaulted: Vec::new(),
        }));
    };
    let mut normalized = Vec::with_capacity(last_slot + 1);
    let mut defaulted = Vec::with_capacity(last_slot + 1);
    for index in 0..=last_slot {
        if let Some(argument) = &slots[index] {
            normalized.push(argument.clone());
            defaulted.push(false);
        } else if let Some(default) = parameters[index].default {
            normalized.push(internal_parameter_default_expr(default));
            defaulted.push(true);
        } else {
            return None;
        }
    }
    Some(Ok(BoundInternalArguments {
        arguments: normalized,
        defaulted,
    }))
}

