fn emit_only_variables_assigned_by_reference_notice(out: &mut String, indent: &str, line: usize) {
    out.push_str(indent);
    out.push_str("ptn_emit_only_variables_assigned_by_reference_notice_at(&runtime, ");
    out.push_str(&line.to_string());
    out.push_str(");\n");
}

fn emit_only_variables_assigned_by_reference_notice_unless_return_fallback(
    out: &mut String,
    indent: &str,
    line: usize,
    source_temp: &str,
) {
    out.push_str(indent);
    out.push_str("if (!ptn_value_is_return_reference_fallback(");
    out.push_str(source_temp);
    out.push_str(")) {\n");
    let nested_indent = format!("{indent}    ");
    emit_only_variables_assigned_by_reference_notice(out, &nested_indent, line);
    out.push_str(indent);
    out.push_str("}\n");
}

fn emit_unwrap_array_dim_reference_call_argument(out: &mut String, indent: &str, temp: &str) {
    out.push_str(indent);
    out.push_str("ptn_runtime_unwrap_reference_slots_if_unaliased(&runtime, ");
    out.push_str(temp);
    out.push_str(", 3);\n");
}

fn reference_target_from_value(value: &ValueExpr) -> Option<ReferenceTarget> {
    match value {
        ValueExpr::Load { name, line } => Some(ReferenceTarget::Variable {
            name: name.clone(),
            line: *line,
        }),
        ValueExpr::DynamicVariable { name, line } => Some(ReferenceTarget::DynamicVariable {
            name: name.clone(),
            line: *line,
        }),
        ValueExpr::ArrayAccess { .. } | ValueExpr::ArrayAppendAccess { .. } => {
            reference_array_dim_target_from_value(value)
        }
        ValueExpr::PropertyFetch {
            receiver,
            name,
            line,
        } => Some(ReferenceTarget::Property {
            receiver: receiver.clone(),
            name: name.clone(),
            line: *line,
        }),
        ValueExpr::DynamicPropertyFetch {
            receiver,
            name,
            nullsafe,
            line,
        } => {
            if *nullsafe {
                None
            } else {
                Some(ReferenceTarget::DynamicProperty {
                    receiver: receiver.clone(),
                    name: name.clone(),
                    line: *line,
                })
            }
        }
        _ => None,
    }
}

fn by_ref_temporary_argument_allowed(value: &ValueExpr) -> bool {
    matches!(
        value,
        ValueExpr::InternalCall { .. }
            | ValueExpr::DynamicCall { .. }
            | ValueExpr::MethodCall { .. }
            | ValueExpr::DynamicMethodCall { .. }
    )
}

fn call_result_needs_value_deref(value: &ValueExpr) -> bool {
    matches!(
        value,
        ValueExpr::InternalCall { .. }
            | ValueExpr::DynamicCall { .. }
            | ValueExpr::MethodCall { .. }
            | ValueExpr::DynamicMethodCall { .. }
    )
}

fn temporary_array_dim_by_ref_argument_path(
    value: &ValueExpr,
) -> Option<(&ValueExpr, Vec<Option<ValueExpr>>, usize)> {
    let mut dimensions = Vec::new();
    let mut current = value;
    let mut line = value_expr_runtime_line(value).unwrap_or(0);

    loop {
        match current {
            ValueExpr::ArrayAccess {
                array,
                index,
                line: access_line,
            } => {
                line = *access_line;
                dimensions.push(Some((**index).clone()));
                current = array.as_ref();
            }
            ValueExpr::ArrayAppendAccess { .. } => return None,
            ValueExpr::InternalCall { .. }
            | ValueExpr::DynamicCall { .. }
            | ValueExpr::MethodCall { .. }
            | ValueExpr::DynamicMethodCall { .. }
            | ValueExpr::ParentPropertyHookCall { .. } => {
                if dimensions.is_empty() {
                    return None;
                }
                dimensions.reverse();
                return Some((current, dimensions, line));
            }
            _ => return None,
        }
    }
}

fn cursor_temporary_helper_name(name: &str) -> Option<&'static str> {
    if name.eq_ignore_ascii_case("next") {
        Some("ptn_runtime_array_next_temporary")
    } else if name.eq_ignore_ascii_case("end") {
        Some("ptn_runtime_array_end_temporary")
    } else if name.eq_ignore_ascii_case("prev") {
        Some("ptn_runtime_array_prev_temporary")
    } else if name.eq_ignore_ascii_case("reset") {
        Some("ptn_runtime_array_reset_temporary")
    } else {
        None
    }
}

fn value_is_array_dim_reference_target(value: &ValueExpr) -> bool {
    matches!(
        reference_target_from_value(value),
        Some(ReferenceTarget::ArrayDim(_)) | Some(ReferenceTarget::PropertyArrayDim { .. })
    )
}

fn reference_array_dim_target_from_value(value: &ValueExpr) -> Option<ReferenceTarget> {
    let mut dimensions = Vec::new();
    let mut current = value;
    let mut line = None;
    loop {
        match current {
            ValueExpr::ArrayAccess {
                array,
                index,
                line: access_line,
            } => {
                if line.is_none() {
                    line = Some(*access_line);
                }
                dimensions.push(Some((**index).clone()));
                current = array.as_ref();
            }
            ValueExpr::ArrayAppendAccess {
                array,
                line: access_line,
            } => {
                if line.is_none() {
                    line = Some(*access_line);
                }
                dimensions.push(None);
                current = array.as_ref();
            }
            ValueExpr::Load {
                name,
                line: load_line,
            } => {
                dimensions.reverse();
                return Some(ReferenceTarget::ArrayDim(crate::ir::ArrayDimTarget {
                    array: name.clone(),
                    dimensions,
                    line: line.unwrap_or(*load_line),
                }));
            }
            ValueExpr::PropertyFetch {
                receiver,
                name,
                line: property_line,
            } => {
                dimensions.reverse();
                return Some(ReferenceTarget::PropertyArrayDim {
                    receiver: receiver.clone(),
                    name: name.clone(),
                    dimensions,
                    line: line.unwrap_or(*property_line),
                });
            }
            _ => return None,
        }
    }
}

fn property_receiver_is_temporary_write_context(value: &ValueExpr) -> bool {
    matches!(
        value,
        ValueExpr::String(_)
            | ValueExpr::Int(_)
            | ValueExpr::Float(_)
            | ValueExpr::Bool(_)
            | ValueExpr::Null
            | ValueExpr::Array(_)
            | ValueExpr::Closure { .. }
            | ValueExpr::InternalCall { .. }
            | ValueExpr::DynamicCall { .. }
            | ValueExpr::MethodCall { .. }
            | ValueExpr::DynamicMethodCall { .. }
            | ValueExpr::ParentPropertyHookCall { .. }
            | ValueExpr::Binary { .. }
            | ValueExpr::Ternary { .. }
            | ValueExpr::Unary { .. }
            | ValueExpr::Cast { .. }
            | ValueExpr::Clone { .. }
            | ValueExpr::Include { .. }
            | ValueExpr::Throw { .. }
    )
}

fn property_receiver_uses_quiet_unset(value: &ValueExpr) -> bool {
    matches!(
        value,
        ValueExpr::PropertyFetch { .. }
            | ValueExpr::DynamicPropertyFetch { .. }
            | ValueExpr::StaticPropertyFetch { .. }
            | ValueExpr::ArrayAccess { .. }
    )
}

fn value_is_temporary_write_context(value: &ValueExpr) -> bool {
    match value {
        ValueExpr::ArrayAccess { .. } | ValueExpr::ArrayAppendAccess { .. } => {
            reference_array_dim_target_from_value(value).is_none()
        }
        ValueExpr::PropertyFetch { receiver, .. }
        | ValueExpr::DynamicPropertyFetch { receiver, .. } => {
            property_receiver_is_temporary_write_context(receiver)
        }
        _ => false,
    }
}

fn value_is_reference_list_assignment(value: &ValueExpr) -> bool {
    matches!(
        value,
        ValueExpr::Assign {
            target: AssignmentTarget::List(target),
            op: AssignmentOp::Assign,
            ..
        } if list_assignment_has_reference(target)
    )
}

fn value_needs_runtime_by_ref_argument_check(value: &ValueExpr) -> bool {
    value_is_temporary_write_context(value)
        || value_is_reference_list_assignment(value)
        || matches!(
            value,
            ValueExpr::NullsafePropertyFetch { .. } | ValueExpr::PipeValue { .. }
        )
}

fn emit_switch(
    out: &mut String,
    values: &mut ValueEmitter,
    expression: &ValueExpr,
    cases: &[crate::ir::SwitchCase],
    control_targets: &mut Vec<ControlTarget>,
    finally_stack: &mut Vec<FinallyContext>,
    source_path: &str,
    return_target: Option<&str>,
    label_scope: Option<&LabelScope<'_>>,
) {
    let end_label = values.next_label("ptn_switch_end");
    emit_label_reference(out, &end_label);
    let labels: Vec<String> = cases
        .iter()
        .map(|_| values.next_label("ptn_switch_case"))
        .collect();
    let switch_temp = values.emit_materialized_value(out, expression);
    if cases.iter().all(|case| case.condition.is_none()) {
        out.push_str("    (void)");
        out.push_str(&switch_temp);
        out.push_str(";\n");
    }
    let mut default_label = None;

    for (case, label) in cases.iter().zip(labels.iter()) {
        if let Some(condition) = &case.condition {
            out.push_str("    {\n");
            let condition_temp = values.emit_materialized_value(out, condition);
            let matched_temp = values.next_temp();
            out.push_str("        int ");
            out.push_str(&matched_temp);
            out.push_str(" = ptn_compare_equal(&runtime, ");
            out.push_str(&switch_temp);
            out.push_str(", ");
            out.push_str(&condition_temp);
            out.push_str(", runtime.call_site_line);\n");
            emit_value_cleanup(out, "        ", &condition_temp);
            out.push_str("        if (");
            out.push_str(&matched_temp);
            out.push_str(") {\n");
            emit_value_cleanup(out, "            ", &switch_temp);
            out.push_str("            goto ");
            out.push_str(label);
            out.push_str(";\n");
            out.push_str("        }\n");
            out.push_str("    }\n");
        } else {
            default_label = Some(label.as_str());
        }
    }

    emit_value_cleanup(out, "    ", &switch_temp);
    out.push_str("    goto ");
    out.push_str(default_label.unwrap_or(&end_label));
    out.push_str(";\n");

    for (case, label) in cases.iter().zip(labels.iter()) {
        out.push_str("    ");
        out.push_str(label);
        out.push_str(":\n");
        out.push_str("    ;\n");
        control_targets.push(ControlTarget::switch_target(end_label.clone()));
        for body_instruction in &case.body {
            emit_instruction(
                out,
                values,
                body_instruction,
                control_targets,
                finally_stack,
                source_path,
                return_target,
                label_scope,
            );
        }
        control_targets.pop();
    }

    out.push_str("    ");
    out.push_str(&end_label);
    out.push_str(":\n");
    out.push_str("    ;\n");
}

fn emit_label_reference(out: &mut String, label: &str) {
    out.push_str("    if (0) { goto ");
    out.push_str(label);
    out.push_str("; }\n");
}

fn inc_dec_runtime_function(op: IncDecOp) -> &'static str {
    match op {
        IncDecOp::Increment => "ptn_increment_value",
        IncDecOp::Decrement => "ptn_decrement_value",
    }
}

fn emit_increment_statement(
    out: &mut String,
    values: &mut ValueEmitter,
    target: &IncDecTarget,
    op: IncDecOp,
    line: usize,
    source_path: &str,
) {
    match target {
        IncDecTarget::Variable { name, .. } => {
            let current_temp = values.next_temp();
            out.push_str("    PtnValue ");
            out.push_str(&current_temp);
            out.push_str(" = ptn_runtime_read_variable_for_increment(&runtime, \"");
            out.push_str(&c_string(name));
            out.push_str("\", \"");
            out.push_str(&c_string(source_path));
            out.push_str("\", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            let result_temp = values.next_temp();
            out.push_str("    PtnValue ");
            out.push_str(&result_temp);
            out.push_str(" = ");
            out.push_str(inc_dec_runtime_function(op));
            out.push_str("(&runtime, ");
            out.push_str(&current_temp);
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            out.push_str("    ptn_runtime_write_variable(&runtime, \"");
            out.push_str(&c_string(name));
            out.push_str("\", ");
            out.push_str(&result_temp);
            out.push_str(");\n");
            emit_value_cleanup(out, "    ", &current_temp);
            emit_value_cleanup(out, "    ", &result_temp);
        }
        IncDecTarget::DynamicVariable { .. } | IncDecTarget::DynamicArrayDim { .. } => {
            unreachable!("parser restricts statement inc/dec targets")
        }
        IncDecTarget::ValueArrayDim {
            array, dimensions, ..
        } => {
            let array_temp = values.emit_reference_candidate_value(out, array);
            out.push_str("    ptn_value_separate_temporary_array_root_for_write(&");
            out.push_str(&array_temp);
            out.push_str(");\n");
            let path = emit_array_path_segments(out, values, dimensions);
            let path_snapshot = emit_array_path_value_snapshot(out, values, &path);
            let current_temp = values.next_temp();
            out.push_str("    PtnValue ");
            out.push_str(&current_temp);
            out.push_str(" = ptn_value_array_path_read_for_inc_dec(&runtime, ");
            out.push_str(&array_temp);
            out.push_str(", ");
            out.push_str(&path_snapshot);
            out.push_str(", ");
            out.push_str(&path.len.to_string());
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            let result_temp = values.next_temp();
            out.push_str("    PtnValue ");
            out.push_str(&result_temp);
            out.push_str(" = ");
            out.push_str(inc_dec_runtime_function(op));
            out.push_str("(&runtime, ");
            out.push_str(&current_temp);
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            out.push_str("    ptn_value_array_path_set_from_inc_dec(&runtime, &");
            out.push_str(&array_temp);
            out.push_str(", ");
            out.push_str(&path_snapshot);
            out.push_str(", ");
            out.push_str(&path.len.to_string());
            out.push_str(", ");
            out.push_str(&current_temp);
            out.push_str(", ");
            out.push_str(&result_temp);
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            emit_value_cleanup(out, "    ", &current_temp);
            emit_value_cleanup(out, "    ", &result_temp);
            emit_value_cleanup(out, "    ", &array_temp);
            emit_array_path_value_snapshot_cleanup(out, "    ", &path_snapshot, &path);
            for segment_temp in path.value_temps {
                emit_value_cleanup(out, "    ", &segment_temp);
            }
        }
        IncDecTarget::ArrayDim {
            array, dimensions, ..
        } => {
            out.push_str("    ptn_runtime_array_warn_missing_base_for_assign_op(&runtime, \"");
            out.push_str(&c_string(array));
            out.push_str("\", \"");
            out.push_str(&c_string(source_path));
            out.push_str("\", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            let path = emit_array_path_segments(out, values, dimensions);
            let path_snapshot = emit_array_path_value_snapshot(out, values, &path);
            let current_temp = values.next_temp();
            out.push_str("    PtnValue ");
            out.push_str(&current_temp);
            out.push_str(" = ptn_runtime_array_path_read_for_assign_op(&runtime, \"");
            out.push_str(&c_string(array));
            out.push_str("\", ");
            out.push_str(&path_snapshot);
            out.push_str(", ");
            out.push_str(&path.len.to_string());
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            let result_temp = values.next_temp();
            out.push_str("    PtnValue ");
            out.push_str(&result_temp);
            out.push_str(" = ");
            out.push_str(inc_dec_runtime_function(op));
            out.push_str("(&runtime, ");
            out.push_str(&current_temp);
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            out.push_str("    ptn_runtime_array_path_set_from_inc_dec(&runtime, \"");
            out.push_str(&c_string(array));
            out.push_str("\", ");
            out.push_str(&path_snapshot);
            out.push_str(", ");
            out.push_str(&path.len.to_string());
            out.push_str(", ");
            out.push_str(&current_temp);
            out.push_str(", ");
            out.push_str(&result_temp);
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            emit_value_cleanup(out, "    ", &current_temp);
            emit_value_cleanup(out, "    ", &result_temp);
            emit_array_path_value_snapshot_cleanup(out, "    ", &path_snapshot, &path);
            for segment_temp in path.value_temps {
                emit_value_cleanup(out, "    ", &segment_temp);
            }
        }
        IncDecTarget::PropertyArrayDim { .. }
        | IncDecTarget::Property { .. }
        | IncDecTarget::DynamicProperty { .. }
        | IncDecTarget::StaticProperty { .. }
        | IncDecTarget::StaticPropertyArrayDim { .. }
        | IncDecTarget::DynamicStaticPropertyName { .. } => {
            let result_temp =
                values.emit_inc_dec_expression(out, target, op, IncDecResult::Pre, line);
            emit_value_cleanup(out, "    ", &result_temp);
        }
    }
}

fn emit_value_cleanup(out: &mut String, indent: &str, value: &str) {
    out.push_str(indent);
    out.push_str("ptn_value_drop(&");
    out.push_str(value);
    out.push_str(");\n");
}

fn emit_value_cleanup_with_runtime_line(out: &mut String, indent: &str, value: &str, line: &str) {
    out.push_str(indent);
    out.push_str("ptn_value_destroy_with_runtime_scope_at(&runtime, &");
    out.push_str(value);
    out.push_str(", ");
    out.push_str(line);
    out.push_str(");\n");
}

fn emit_method_receiver_cleanup(out: &mut String, indent: &str, value: &str) {
    out.push_str(indent);
    out.push_str("ptn_generator_flush_pending_output_before_value_drop(&runtime, ");
    out.push_str(value);
    out.push_str(");\n");
    emit_value_cleanup(out, indent, value);
}

fn emit_push_owned_call_argument_roots(
    out: &mut String,
    indent: &str,
    args_temp: &str,
    len: usize,
) {
    for index in (0..len).rev() {
        out.push_str(indent);
        out.push_str("ptn_runtime_push_owned_temporary_root(&runtime, &");
        out.push_str(args_temp);
        out.push('[');
        out.push_str(&index.to_string());
        out.push_str("]);\n");
    }
}

fn emit_pop_owned_call_argument_roots(out: &mut String, indent: &str, len: usize) {
    for _ in 0..len {
        out.push_str(indent);
        out.push_str("ptn_runtime_pop_temporary_root(&runtime);\n");
    }
}

fn is_array_mutating_internal_call(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "array_pop"
            | "array_push"
            | "array_shift"
            | "array_splice"
            | "array_unshift"
            | "array_walk"
            | "array_walk_recursive"
            | "array_multisort"
            | "arsort"
            | "asort"
            | "end"
            | "krsort"
            | "ksort"
            | "natcasesort"
            | "natsort"
            | "next"
            | "prev"
            | "reset"
            | "rsort"
            | "shuffle"
            | "sort"
            | "uasort"
            | "uksort"
            | "usort"
    )
}

fn binary_runtime_function(op: BinaryOp) -> &'static str {
    match op {
        BinaryOp::Add => "ptn_add",
        BinaryOp::Subtract => "ptn_subtract",
        BinaryOp::Multiply => "ptn_multiply",
        BinaryOp::Power => "ptn_power",
        BinaryOp::Divide => "ptn_divide",
        BinaryOp::Modulo => "ptn_modulo",
        BinaryOp::BitwiseAnd => "ptn_bitwise_and",
        BinaryOp::BitwiseXor => "ptn_bitwise_xor",
        BinaryOp::BitwiseOr => "ptn_bitwise_or",
        BinaryOp::ShiftLeft => "ptn_shift_left",
        BinaryOp::ShiftRight => "ptn_shift_right",
        BinaryOp::Concat
        | BinaryOp::Coalesce
        | BinaryOp::Equal
        | BinaryOp::NotEqual
        | BinaryOp::Spaceship
        | BinaryOp::Identical
        | BinaryOp::NotIdentical
        | BinaryOp::Less
        | BinaryOp::LessEqual
        | BinaryOp::Greater
        | BinaryOp::GreaterEqual
        | BinaryOp::And
        | BinaryOp::Xor
        | BinaryOp::Or => unreachable!("not a direct binary runtime helper"),
    }
}

fn binary_left_operand_preserves_operator_order(value: &ValueExpr) -> bool {
    !matches!(
        value,
        ValueExpr::String(_)
            | ValueExpr::Int(_)
            | ValueExpr::Float(_)
            | ValueExpr::Bool(_)
            | ValueExpr::Null
            | ValueExpr::Constant { .. }
            | ValueExpr::MagicConstant { .. }
            | ValueExpr::Array(_)
    )
}

fn binary_runtime_function_for_operands(
    op: BinaryOp,
    left: &ValueExpr,
    _right: &ValueExpr,
) -> &'static str {
    if binary_left_operand_preserves_operator_order(left) {
        match op {
            BinaryOp::Multiply => return "ptn_multiply_preserving_order",
            BinaryOp::BitwiseAnd => return "ptn_bitwise_and_preserving_order",
            BinaryOp::BitwiseXor => return "ptn_bitwise_xor_preserving_order",
            BinaryOp::BitwiseOr => return "ptn_bitwise_or_preserving_order",
            _ => {}
        }
    }
    binary_runtime_function(op)
}

fn compound_binary_runtime_function(op: BinaryOp) -> &'static str {
    match op {
        BinaryOp::Multiply => "ptn_multiply_assign",
        BinaryOp::BitwiseAnd => "ptn_bitwise_and_assign",
        BinaryOp::BitwiseXor => "ptn_bitwise_xor_assign",
        BinaryOp::BitwiseOr => "ptn_bitwise_or_assign",
        _ => binary_runtime_function(op),
    }
}

fn binary_runtime_function_uses_context(op: BinaryOp) -> bool {
    matches!(
        op,
        BinaryOp::Add
            | BinaryOp::Subtract
            | BinaryOp::Multiply
            | BinaryOp::Power
            | BinaryOp::Divide
            | BinaryOp::Modulo
            | BinaryOp::BitwiseAnd
            | BinaryOp::BitwiseXor
            | BinaryOp::BitwiseOr
            | BinaryOp::ShiftLeft
            | BinaryOp::ShiftRight
    )
}

fn binary_runtime_diagnostic_line(left: &ValueExpr, right: &ValueExpr, line: usize) -> usize {
    [
        value_expr_runtime_line(left),
        value_expr_runtime_line(right),
    ]
    .into_iter()
    .flatten()
    .fold(line, usize::max)
}

fn assignment_compound_binary_op(op: AssignmentOp) -> Option<BinaryOp> {
    match op {
        AssignmentOp::Assign | AssignmentOp::CoalesceAssign => None,
        AssignmentOp::AddAssign => Some(BinaryOp::Add),
        AssignmentOp::SubtractAssign => Some(BinaryOp::Subtract),
        AssignmentOp::MultiplyAssign => Some(BinaryOp::Multiply),
        AssignmentOp::PowerAssign => Some(BinaryOp::Power),
        AssignmentOp::DivideAssign => Some(BinaryOp::Divide),
        AssignmentOp::ModuloAssign => Some(BinaryOp::Modulo),
        AssignmentOp::ConcatAssign => Some(BinaryOp::Concat),
        AssignmentOp::BitwiseAndAssign => Some(BinaryOp::BitwiseAnd),
        AssignmentOp::BitwiseOrAssign => Some(BinaryOp::BitwiseOr),
        AssignmentOp::BitwiseXorAssign => Some(BinaryOp::BitwiseXor),
        AssignmentOp::ShiftLeftAssign => Some(BinaryOp::ShiftLeft),
        AssignmentOp::ShiftRightAssign => Some(BinaryOp::ShiftRight),
    }
}

pub fn compile_c(c_source: &str, output: &Path) -> Result<()> {
    let c_path = output.with_extension("c");
    fs::write(&c_path, c_source).map_err(|error| {
        Diagnostic::new(
            format!(
                "failed to write generated C source {}: {error}",
                c_path.display()
            ),
            None,
        )
    })?;
    let optimization_args = cc_optimization_args(c_source.len())?;
    let warning_args = cc_warning_args(c_source.len())?;
    let openssl_config = discover_openssl_compile_config();
    let zlib_config = discover_zlib_compile_config();
    if c_source_uses_ada_url(c_source) {
        return compile_c_with_ada_url(
            &c_path,
            output,
            &optimization_args,
            &warning_args,
            openssl_config.as_ref(),
            zlib_config.as_ref(),
        );
    }
    let mut command = toolchain_command("cc", "CC");
    command.arg("-std=c11");
    add_pcre2_default_library_define(&mut command);
    if let Some(config) = openssl_config.as_ref() {
        add_openssl_compile_args(&mut command, config);
    }
    if let Some(config) = zlib_config.as_ref() {
        add_zlib_compile_args(&mut command, config);
    }
    for arg in warning_args {
        command.arg(arg);
    }
    for arg in optimization_args {
        command.arg(arg);
    }
    if cfg!(target_family = "unix") {
        command.arg("-pthread");
    }
    let status = command
        .arg(&c_path)
        .arg("-o")
        .arg(output)
        .args(if cfg!(target_os = "linux") {
            &["-ldl"][..]
        } else {
            &[]
        })
        .args(
            openssl_config
                .as_ref()
                .map(openssl_link_args)
                .unwrap_or_default(),
        )
        .args(zlib_config.as_ref().map(zlib_link_args).unwrap_or_default())
        .arg("-lm")
        .status()
        .map_err(|error| Diagnostic::new(format!("failed to launch cc: {error}"), None))?;
    if status.success() {
        Ok(())
    } else {
        Err(Diagnostic::new(
            format!(
                "cc failed compiling {} to {}",
                display_os(c_path.as_os_str()),
                display_os(output.as_os_str())
            ),
            None,
        ))
    }
}

fn compile_c_with_ada_url(
    c_path: &Path,
    output: &Path,
    optimization_args: &[&str],
    warning_args: &[&str],
    openssl_config: Option<&OpenSslCompileConfig>,
    zlib_config: Option<&ZlibCompileConfig>,
) -> Result<()> {
    let ada_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("third_party/ada-url-3.4.5");
    let ada_cpp = ada_dir.join("ada.cpp");
    let c_object = output.with_extension("ptn-c.o");
    let ada_object = output.with_extension("ptn-ada-url.o");

    let mut c_command = toolchain_command("cc", "CC");
    c_command.arg("-std=c11");
    add_pcre2_default_library_define(&mut c_command);
    if let Some(config) = openssl_config {
        add_openssl_compile_args(&mut c_command, config);
    }
    if let Some(config) = zlib_config {
        add_zlib_compile_args(&mut c_command, config);
    }
    for arg in warning_args {
        c_command.arg(arg);
    }
    for arg in optimization_args {
        c_command.arg(arg);
    }
    if cfg!(target_family = "unix") {
        c_command.arg("-pthread");
    }
    let c_status = c_command
        .arg("-I")
        .arg(&ada_dir)
        .arg("-c")
        .arg(c_path)
        .arg("-o")
        .arg(&c_object)
        .status()
        .map_err(|error| Diagnostic::new(format!("failed to launch cc: {error}"), None))?;
    if !c_status.success() {
        let _ = fs::remove_file(&c_object);
        return Err(Diagnostic::new(
            format!(
                "cc failed compiling {} to object",
                display_os(c_path.as_os_str())
            ),
            None,
        ));
    }

    let mut ada_command = toolchain_command("c++", "CXX");
    ada_command
        .arg("-std=c++20")
        .arg("-DADA_INCLUDE_URL_PATTERN=0");
    for arg in optimization_args {
        ada_command.arg(arg);
    }
    if cfg!(target_family = "unix") {
        ada_command.arg("-pthread");
    }
    let ada_status = ada_command
        .arg("-I")
        .arg(&ada_dir)
        .arg("-c")
        .arg(&ada_cpp)
        .arg("-o")
        .arg(&ada_object)
        .status()
        .map_err(|error| Diagnostic::new(format!("failed to launch c++: {error}"), None))?;
    if !ada_status.success() {
        let _ = fs::remove_file(&c_object);
        let _ = fs::remove_file(&ada_object);
        return Err(Diagnostic::new(
            format!(
                "c++ failed compiling vendored Ada URL parser {}",
                display_os(ada_cpp.as_os_str())
            ),
            None,
        ));
    }

    let mut link_command = toolchain_command("c++", "CXX");
    link_command
        .arg(&c_object)
        .arg(&ada_object)
        .arg("-o")
        .arg(output);
    if cfg!(target_os = "linux") {
        link_command.arg("-ldl");
    }
    if cfg!(target_family = "unix") {
        link_command.arg("-pthread");
    }
    if let Some(config) = openssl_config {
        link_command.args(openssl_link_args(config));
    }
    if let Some(config) = zlib_config {
        link_command.args(zlib_link_args(config));
    }
    let link_status = link_command
        .arg("-lm")
        .status()
        .map_err(|error| Diagnostic::new(format!("failed to launch c++ linker: {error}"), None))?;
    let _ = fs::remove_file(&c_object);
    let _ = fs::remove_file(&ada_object);
    if link_status.success() {
        Ok(())
    } else {
        Err(Diagnostic::new(
            format!(
                "c++ failed linking {} to {}",
                display_os(c_path.as_os_str()),
                display_os(output.as_os_str())
            ),
            None,
        ))
    }
}

fn toolchain_command(program: &str, env_var: &str) -> Command {
    Command::new(resolve_toolchain_binary(program, env_var))
}

fn resolve_toolchain_binary(program: &str, env_var: &str) -> PathBuf {
    if let Some(value) = env::var_os(env_var) {
        if !value.as_os_str().is_empty() {
            return PathBuf::from(value);
        }
    }
    if let Some(path) = find_program_on_path(program) {
        return path;
    }
    for dir in [
        "/run/current-system/sw/bin",
        "/usr/local/bin",
        "/usr/bin",
        "/bin",
    ] {
        let candidate = Path::new(dir).join(program);
        if candidate.is_file() {
            return candidate;
        }
    }
    PathBuf::from(program)
}

fn find_program_on_path(program: &str) -> Option<PathBuf> {
    let paths = env::var_os("PATH")?;
    for dir in env::split_paths(&paths) {
        let candidate = dir.join(program);
        if candidate.is_file() {
            return Some(candidate);
        }
    }
    None
}

#[derive(Debug)]
struct OpenSslCompileConfig {
    include_dir: PathBuf,
    lib_dir: PathBuf,
}

#[derive(Debug)]
struct ZlibCompileConfig {
    include_dir: PathBuf,
    lib_dir: PathBuf,
}

