        out.push_str(");\n");

        let notice_emitted_temp = self.next_temp();
        out.push_str("    int ");
        out.push_str(&notice_emitted_temp);
        out.push_str(" = ptn_object_emit_indirect_modification_overloaded_property_notice_for_value(&runtime, ");
        out.push_str(&receiver_temp);
