        out.push_str(", ");
        out.push_str(&display_path_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(", ");
        out.push_str(if include_kind_is_once(kind) { "1" } else { "0" });
        out.push_str(", &");
        out.push_str(&dynamic_include_suppressed_open_warning_temp);
        out.push_str(", &");
        out.push_str(&result_temp);
