        out.push_str("    if (");
        out.push_str(&lookup_temp);
        out.push_str(".exists && ptn_value_deref(");
        out.push_str(&lookup_temp);
        out.push_str(".value).type != PTN_NULL) {\n");
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_value_clone_deref(");
        out.push_str(&lookup_temp);
