    fn emit_property_probe_quiet(
        &mut self,
        out: &mut String,
        receiver: &ValueExpr,
        name: &str,
        line: usize,
    ) -> String {
        let receiver_lookup_temp = self.emit_quiet_lookup_for_dereference_receiver(out, receiver);
        let lookup_temp = self.next_temp();
        out.push_str("        PtnLookupResult ");
        out.push_str(&lookup_temp);
        out.push_str(";\n");
        out.push_str("        if (");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".exists) {\n");
        out.push_str("            ");
        out.push_str(&lookup_temp);
        out.push_str(" = ptn_object_property_probe_quiet(&runtime, ");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".value, \"");
        out.push_str(&c_string(name));
        out.push_str("\", ");
        self.emit_access_scope(out);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        out.push_str("        } else {\n");
        out.push_str("            ");
        out.push_str(&lookup_temp);
        out.push_str(" = ptn_lookup_missing();\n");
        out.push_str("        }\n");
        emit_value_cleanup(out, "        ", &format!("{receiver_lookup_temp}.value"));
        lookup_temp
    }

    fn emit_quiet_lookup_for_unset_receiver(
        &mut self,
        out: &mut String,
        value: &ValueExpr,
    ) -> String {
        match value {
            ValueExpr::PropertyFetch {
                receiver,
                name,
                line,
            } => self.emit_property_probe_quiet_for_unset_receiver(out, receiver, name, *line),
            _ => self.emit_quiet_lookup(out, value),
        }
    }

    fn emit_property_probe_quiet_for_unset_receiver(
        &mut self,
        out: &mut String,
        receiver: &ValueExpr,
        name: &str,
        line: usize,
    ) -> String {
        let receiver_lookup_temp = self.emit_quiet_lookup_for_unset_receiver(out, receiver);
        let lookup_temp = self.next_temp();
        out.push_str("        PtnLookupResult ");
        out.push_str(&lookup_temp);
        out.push_str(";\n");
        out.push_str("        if (");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".exists) {\n");
        out.push_str("            ");
        out.push_str(&lookup_temp);
        out.push_str(" = ptn_object_property_probe_quiet(&runtime, ");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".value, \"");
        out.push_str(&c_string(name));
        out.push_str("\", ");
        self.emit_access_scope(out);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        out.push_str("            if (!");
        out.push_str(&lookup_temp);
        out.push_str(".exists && ptn_value_deref(");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".value).type == PTN_OBJECT) {\n");
        let null_temp = self.next_temp();
        let assigned_temp = self.next_temp();
        out.push_str("                PtnValue ");
        out.push_str(&null_temp);
        out.push_str(" = ptn_null();\n");
        out.push_str("                PtnValue ");
        out.push_str(&assigned_temp);
        out.push_str(" = ptn_object_write_property_indirect(&runtime, ");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".value, \"");
        out.push_str(&c_string(name));
        out.push_str("\", ");
        self.emit_access_scope(out);
        out.push_str(", ");
        out.push_str(&null_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        out.push_str("                ptn_value_destroy(&");
        out.push_str(&assigned_temp);
        out.push_str(");\n");
        out.push_str("            }\n");
        out.push_str("        } else {\n");
        out.push_str("            ");
        out.push_str(&lookup_temp);
        out.push_str(" = ptn_lookup_missing();\n");
        out.push_str("        }\n");
        emit_value_cleanup(out, "        ", &format!("{receiver_lookup_temp}.value"));
        lookup_temp
    }

    fn emit_dynamic_property_probe_quiet(
        &mut self,
        out: &mut String,
        receiver: &ValueExpr,
        name: &ValueExpr,
        nullsafe: bool,
        line: usize,
    ) -> String {
        let receiver_lookup_temp = self.emit_quiet_lookup_for_dereference_receiver(out, receiver);
        let eager_name_value_temp = (!nullsafe).then(|| self.emit_materialized_value(out, name));
        let lookup_temp = self.next_temp();
        out.push_str("        PtnLookupResult ");
        out.push_str(&lookup_temp);
        out.push_str(";\n");
        out.push_str("        if (");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".exists");
        if nullsafe {
            out.push_str(" && ptn_value_deref(");
            out.push_str(&receiver_lookup_temp);
            out.push_str(".value).type != PTN_NULL");
        }
        out.push_str(") {\n");
        let name_temp = if let Some(value_temp) = eager_name_value_temp.as_ref() {
            let name_temp = self.next_temp();
            out.push_str("            char *");
            out.push_str(&name_temp);
            out.push_str(" = ");
            out.push_str(
                if value_expr_is_compile_time_array_dynamic_property_name(name) {
                    "ptn_dynamic_property_name_without_array_warning"
                } else {
                    "ptn_dynamic_property_name"
                },
            );
            out.push_str("(&runtime, ");
            out.push_str(value_temp);
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            name_temp
        } else {
            self.emit_dynamic_property_name(out, name, line)
        };
        out.push_str("            ");
        out.push_str(&lookup_temp);
        out.push_str(" = ptn_object_property_probe_quiet(&runtime, ");
        out.push_str(&receiver_lookup_temp);
        out.push_str(".value, ");
        out.push_str(&name_temp);
        out.push_str(", ");
        self.emit_access_scope(out);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        out.push_str("            free(");
        out.push_str(&name_temp);
        out.push_str(");\n");
        out.push_str("        } else {\n");
        out.push_str("            ");
        out.push_str(&lookup_temp);
        out.push_str(" = ptn_lookup_missing();\n");
        out.push_str("        }\n");
        if let Some(value_temp) = eager_name_value_temp {
            emit_value_cleanup(out, "        ", &value_temp);
        }
        emit_value_cleanup(out, "        ", &format!("{receiver_lookup_temp}.value"));
        lookup_temp
    }

