    fn emit_quiet_lookup(&mut self, out: &mut String, value: &ValueExpr) -> String {
        match value {
            ValueExpr::Load { name, .. } => {
                let result_temp = self.next_temp();
                out.push_str("        PtnLookupResult ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_runtime_read_variable_quiet(&runtime, \"");
                out.push_str(&c_string(name));
                out.push_str("\");\n");
                result_temp
            }
            ValueExpr::LegacyDollarBraceExpressionVariable { name, line }
            | ValueExpr::DynamicVariable { name, line } => {
                self.emit_dynamic_variable_quiet_lookup(out, name, *line)
            }
            ValueExpr::ArrayAccess { array, index, line } => {
                let container_temp = self.emit_quiet_lookup_for_dereference_receiver(out, array);
                let index_temp = self.emit_materialized_value(out, index);
                let result_temp = self.next_temp();
                out.push_str("        PtnLookupResult ");
                out.push_str(&result_temp);
                out.push_str(";\n");
                out.push_str("        if (");
                out.push_str(&container_temp);
                out.push_str(".exists) {\n");
                out.push_str("            ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_offset_lookup(&runtime, ");
                out.push_str(&container_temp);
                out.push_str(".value, ");
                out.push_str(&index_temp);
                out.push_str(", ");
                out.push_str(&line.to_string());
                out.push_str(", 1);\n");
                out.push_str("        } else {\n");
                out.push_str("            ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_lookup_missing();\n");
                out.push_str("        }\n");
                emit_value_cleanup(out, "        ", &format!("{container_temp}.value"));
                emit_value_cleanup(out, "        ", &index_temp);
                result_temp
            }
            ValueExpr::PropertyFetch {
                receiver,
                name,
                line,
            } => self.emit_property_probe_quiet(out, receiver, name, *line),
            ValueExpr::NullsafePropertyFetch {
                receiver,
                name,
                line,
            } => self.emit_nullsafe_property_probe_quiet(out, receiver, name, *line),
            ValueExpr::DynamicPropertyFetch {
                receiver,
                name,
                nullsafe,
                line,
            } => self.emit_dynamic_property_probe_quiet(out, receiver, name, *nullsafe, *line),
            ValueExpr::StaticPropertyFetch {
                class_name,
                name,
                line,
            } => self.emit_static_property_lookup_quiet(out, class_name, name, *line),
            _ => {
                let value_temp = self.emit_materialized_value(out, value);
                let result_temp = self.next_temp();
                out.push_str("        PtnLookupResult ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_lookup_found(");
                out.push_str(&value_temp);
                out.push_str(");\n");
                result_temp
            }
        }
    }

    fn emit_array(&mut self, out: &mut String, elements: &[IrArrayElement]) -> String {
        let result_temp = self.next_temp();
        if elements.is_empty() {
            out.push_str("    PtnValue ");
            out.push_str(&result_temp);
            out.push_str(" = ptn_array_from_literal_entries(0, NULL);\n");
            return result_temp;
        }

        let first_runtime_line = elements
            .iter()
            .map(array_element_runtime_line)
            .find(|line| *line != 0)
            .unwrap_or(0);
        let has_split_runtime_lines = first_runtime_line != 0
            && elements
                .iter()
                .map(array_element_runtime_line)
                .any(|line| line != 0 && line != first_runtime_line);
        let requires_incremental_literal = elements
            .iter()
            .any(|element| matches!(element.value, IrArrayElementValue::Unpack { .. }))
            || has_split_runtime_lines;

        if requires_incremental_literal {
            out.push_str("    PtnValue ");
            out.push_str(&result_temp);
            out.push_str(" = ptn_array_from_literal_entries(0, NULL);\n");
            for element in elements {
                match &element.value {
                    IrArrayElementValue::Value(_) | IrArrayElementValue::Reference(_) => {
                        let (has_key, key_temp) = if let Some(key) = &element.key {
                            let key_temp = self.emit_materialized_value(out, key);
                            ("1", key_temp)
                        } else {
                            ("0", "ptn_null()".to_string())
                        };
                        let value_temp = match &element.value {
                            IrArrayElementValue::Value(value) => {
                                self.emit_materialized_value(out, value)
                            }
                            IrArrayElementValue::Reference(target) => {
                                self.emit_reference_target(out, target)
                            }
                            IrArrayElementValue::Unpack { .. } => unreachable!(),
                        };
                        out.push_str("    ptn_array_literal_append_entry(&runtime, ");
                        out.push_str(&result_temp);
                        out.push_str(".as.array, ");
                        out.push_str(&array_element_runtime_line(element).to_string());
                        out.push_str(", ");
                        out.push_str(has_key);
                        out.push_str(", ");
                        out.push_str(&key_temp);
                        out.push_str(", ");
                        out.push_str(&value_temp);
                        out.push_str(");\n");
                        if element.key.is_some() {
                            emit_value_cleanup(out, "    ", &key_temp);
                        }
                        emit_value_cleanup(out, "    ", &value_temp);
                    }
                    IrArrayElementValue::Unpack { value, line } => {
                        if self.in_const_declaration
                            && const_array_unpack_operand_short_circuits(value)
                        {
                            out.push_str("    ptn_array_unpack_const_invalid(&runtime, ");
                            out.push_str(&line.to_string());
                            out.push_str(");\n");
                            continue;
                        }
                        let value_temp = self.emit_materialized_value(out, value);
                        let unpack_fn = if self.in_const_declaration {
                            "ptn_array_unpack_const_into"
                        } else if unpack_requires_literal_fatal(value) {
                            "ptn_array_unpack_into_or_fatal"
                        } else {
                            "ptn_array_unpack_into"
                        };
                        out.push_str("    ");
                        out.push_str(unpack_fn);
                        out.push_str("(&runtime, ");
                        out.push_str(&result_temp);
                        out.push_str(".as.array, ");
                        out.push_str(&value_temp);
                        out.push_str(", ");
                        out.push_str(&line.to_string());
                        out.push_str(");\n");
                        emit_value_cleanup(out, "    ", &value_temp);
                    }
                }
            }
            return result_temp;
        }

        let mut entries = Vec::with_capacity(elements.len());
        let mut entry_temps = Vec::with_capacity(elements.len() * 2);
        for element in elements {
            let (has_key, key_temp) = if let Some(key) = &element.key {
                let key_temp = self.emit_materialized_value(out, key);
                entry_temps.push(key_temp.clone());
                ("1", key_temp)
            } else {
                ("0", "ptn_null()".to_string())
            };
            let value_temp = match &element.value {
                IrArrayElementValue::Value(value) => self.emit_materialized_value(out, value),
                IrArrayElementValue::Reference(target) => self.emit_reference_target(out, target),
                IrArrayElementValue::Unpack { .. } => unreachable!(),
            };
            entry_temps.push(value_temp.clone());
            entries.push(format!("{{ {has_key}, {key_temp}, {value_temp} }}"));
        }

        let entries_temp = self.next_temp();
        let array_line = elements
            .iter()
            .map(array_element_runtime_line)
            .find(|line| *line != 0)
            .unwrap_or(0);
        out.push_str("    PtnArrayLiteralEntry ");
        out.push_str(&entries_temp);
        out.push_str("[] = { ");
        out.push_str(&entries.join(", "));
        out.push_str(" };\n");
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_array_from_literal_entries_at(&runtime, ");
        out.push_str(&array_line.to_string());
        out.push_str(", ");
        out.push_str(&elements.len().to_string());
        out.push_str(", ");
        out.push_str(&entries_temp);
        out.push_str(");\n");
        for temp in entry_temps {
            emit_value_cleanup(out, "    ", &temp);
        }
        result_temp
    }

    fn emit_short_circuit(
        &mut self,
        out: &mut String,
        op: BinaryOp,
        left: &ValueExpr,
        right: &ValueExpr,
    ) -> String {
        let left_predicate = self.emit_condition(out, left);
        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(";\n");
        out.push_str("    if (");
        out.push_str(&left_predicate);
        out.push_str(") {\n");
        match op {
            BinaryOp::And => {
                let right_predicate = self.emit_condition(out, right);
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_bool(");
                out.push_str(&right_predicate);
                out.push_str(");\n");
                out.push_str("    } else {\n");
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_bool(0);\n");
            }
            BinaryOp::Or => {
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_bool(1);\n");
                out.push_str("    } else {\n");
                let right_predicate = self.emit_condition(out, right);
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_bool(");
                out.push_str(&right_predicate);
                out.push_str(");\n");
            }
            _ => unreachable!(),
        }
        out.push_str("    }\n");
        result_temp
    }

    fn emit_short_circuit_condition(
        &mut self,
        out: &mut String,
        op: BinaryOp,
        left: &ValueExpr,
        right: &ValueExpr,
    ) -> String {
        let left_predicate = self.emit_condition(out, left);
        let result_temp = self.next_temp();
        out.push_str("    int ");
        out.push_str(&result_temp);
        out.push_str(" = 0;\n");
        out.push_str("    if (");
        out.push_str(&left_predicate);
        out.push_str(") {\n");
        match op {
            BinaryOp::And => {
                let right_predicate = self.emit_condition(out, right);
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = (");
                out.push_str(&right_predicate);
                out.push_str(") != 0;\n");
                out.push_str("    } else {\n");
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = 0;\n");
            }
            BinaryOp::Or => {
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = 1;\n");
                out.push_str("    } else {\n");
                let right_predicate = self.emit_condition(out, right);
                out.push_str("        ");
                out.push_str(&result_temp);
                out.push_str(" = (");
                out.push_str(&right_predicate);
                out.push_str(") != 0;\n");
            }
            _ => unreachable!(),
        }
        out.push_str("    }\n");
        result_temp
    }

    fn emit_boolean_xor_condition(
        &mut self,
        out: &mut String,
        left: &ValueExpr,
        right: &ValueExpr,
    ) -> String {
        let left_predicate = self.emit_condition(out, left);
        let left_temp = self.next_temp();
        out.push_str("    int ");
        out.push_str(&left_temp);
        out.push_str(" = (");
        out.push_str(&left_predicate);
        out.push_str(") != 0;\n");
        let right_predicate = self.emit_condition(out, right);
        format!("{left_temp} != (({right_predicate}) != 0)")
    }

    fn emit_boolean_xor(
        &mut self,
        out: &mut String,
        left: &ValueExpr,
        right: &ValueExpr,
    ) -> String {
        let left_predicate = self.emit_condition(out, left);
        let right_predicate = self.emit_condition(out, right);
        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_bool((");
        out.push_str(&left_predicate);
        out.push_str(") != (");
        out.push_str(&right_predicate);
        out.push_str("));\n");
        result_temp
    }

    fn emit_raw_call_result(&mut self, out: &mut String, value: &ValueExpr) -> Option<String> {
        match value {
            ValueExpr::InternalCall {
                name,
                arguments,
                argument_names,
                argument_unpacks,
                allow_global_fallback,
                line,
            } => Some(self.emit_internal_call(
                out,
                name,
                arguments,
                argument_names,
                argument_unpacks,
                &[],
                *allow_global_fallback,
                *line,
                false,
            )),
            ValueExpr::DynamicCall {
                callee,
                arguments,
                argument_names,
                argument_unpacks,
                static_method_syntax,
                line,
            } => Some(self.emit_dynamic_call(
                out,
                callee,
                arguments,
                argument_names,
                argument_unpacks,
                *static_method_syntax,
                *line,
                false,
            )),
            ValueExpr::MethodCall {
                receiver,
                name,
                arguments,
                argument_names,
                argument_unpacks,
                nullsafe,
                line,
            } => Some(if *nullsafe {
                self.emit_nullsafe_method_call(
                    out,
                    receiver,
                    name,
                    arguments,
                    argument_names,
                    argument_unpacks,
                    *line,
                    false,
                )
            } else {
                self.emit_method_call(
                    out,
                    receiver,
                    name,
                    arguments,
                    argument_names,
                    argument_unpacks,
                    *line,
                    false,
                )
            }),
            ValueExpr::DynamicMethodCall {
                receiver,
                name,
                arguments,
                argument_names,
                argument_unpacks,
                line,
            } => Some(self.emit_dynamic_method_call(
                out,
                receiver,
                name,
                arguments,
                argument_names,
                argument_unpacks,
                *line,
                false,
            )),
            ValueExpr::ParentPropertyHookCall {
                property_name,
                hook_name,
                arguments,
                argument_names,
                argument_unpacks,
                line,
            } => Some(self.emit_parent_property_hook_call(
                out,
                property_name,
                hook_name,
                arguments,
                argument_names,
                argument_unpacks,
                *line,
            )),
            _ => None,
        }
    }

    fn emit_reference_candidate_value(&mut self, out: &mut String, value: &ValueExpr) -> String {
        self.emit_raw_call_result(out, value)
            .unwrap_or_else(|| self.emit_materialized_value(out, value))
    }

    fn emit_materialized_value(&mut self, out: &mut String, value: &ValueExpr) -> String {
        let temp = self.emit_raw_materialized_value(out, value);
        if !call_result_needs_value_deref(value) {
            return temp;
        }

        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(";\n");
        out.push_str("    if (");
        out.push_str(&temp);
        out.push_str(".type == PTN_REFERENCE) {\n");
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_value_clone_deref(");
        out.push_str(&temp);
        out.push_str(");\n");
        emit_value_cleanup(out, "        ", &temp);
        out.push_str("    } else {\n");
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&temp);
        out.push_str(";\n");
        out.push_str("    }\n");
        result_temp
    }

    fn emit_owned_method_receiver(&mut self, out: &mut String, receiver: &ValueExpr) -> String {
        let raw_temp = self.emit_materialized_value(out, receiver);
        let receiver_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&receiver_temp);
        out.push_str(";\n");
        out.push_str("    if (ptn_value_is_nullsafe_short_circuit(");
        out.push_str(&raw_temp);
        out.push_str(")) {\n");
        out.push_str("        ");
        out.push_str(&receiver_temp);
        out.push_str(" = ptn_nullsafe_short_circuit();\n");
        out.push_str("    } else {\n");
        out.push_str("        ");
        out.push_str(&receiver_temp);
        out.push_str(" = ptn_value_clone_deref(");
        out.push_str(&raw_temp);
        out.push_str(");\n");
        out.push_str("    }\n");
        emit_value_cleanup(out, "    ", &raw_temp);
        receiver_temp
    }

    fn emit_raw_materialized_value(&mut self, out: &mut String, value: &ValueExpr) -> String {
        if matches!(
            value,
            ValueExpr::Binary { .. }
                | ValueExpr::Assign { .. }
                | ValueExpr::AssignRef { .. }
                | ValueExpr::IncDec { .. }
                | ValueExpr::FirstClassCallable { .. }
                | ValueExpr::Unary { .. }
                | ValueExpr::Cast { .. }
                | ValueExpr::Array(_)
                | ValueExpr::Closure { .. }
                | ValueExpr::ArrayAccess { .. }
                | ValueExpr::ArrayAppendAccess { .. }
                | ValueExpr::LegacyDollarBraceStringVariable { .. }
                | ValueExpr::LegacyDollarBraceExpressionVariable { .. }
                | ValueExpr::DynamicVariable { .. }
                | ValueExpr::Isset { .. }
                | ValueExpr::Empty { .. }
                | ValueExpr::Ternary { .. }
                | ValueExpr::Match { .. }
                | ValueExpr::Clone { .. }
                | ValueExpr::DynamicPropertyFetch { .. }
                | ValueExpr::StaticPropertyFetch { .. }
                | ValueExpr::DynamicStaticPropertyFetch { .. }
                | ValueExpr::ClassConstantFetch { .. }
                | ValueExpr::DynamicClassConstantFetch { .. }
                | ValueExpr::DynamicClassNameFetch { .. }
                | ValueExpr::Include { .. }
                | ValueExpr::Throw { .. }
                | ValueExpr::Yield { .. }
                | ValueExpr::YieldFrom { .. }
                | ValueExpr::NewObject { .. }
                | ValueExpr::DynamicNewObject { .. }
        ) {
            return self.emit_value(out, value);
        }

        let temp = self.next_temp();
        let emitted_value = self.emit_value(out, value);
        out.push_str("    PtnValue ");
        out.push_str(&temp);
        out.push_str(" = ");
        out.push_str(&emitted_value);
        out.push_str(";\n");
        temp
    }

    fn emit_call_argument(
        &mut self,
        out: &mut String,
        call_name: &str,
        argument_index: usize,
        argument: &ValueExpr,
    ) -> String {
        if argument_index == 0 && is_array_mutating_internal_call(call_name) {
            if let ValueExpr::Load { name, line } = argument {
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_runtime_read_variable_for_array_mutation(&runtime, \"");
                out.push_str(&c_string(name));
                out.push_str("\", \"");
                out.push_str(&c_string(&self.source_file));
                out.push_str("\", ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                return temp;
            }
        }

        self.emit_materialized_value(out, argument)
    }

    fn emit_dynamic_call_argument(&mut self, out: &mut String, argument: &ValueExpr) -> String {
        match reference_target_from_value(argument) {
            Some(target) => self.emit_reference_target(out, &target),
            None => self.emit_materialized_value(out, argument),
        }
    }

    fn emit_runtime_declared_method_call_argument(
        &mut self,
        out: &mut String,
        receiver_temp: &str,
        method_name: &str,
        argument_index: usize,
        argument: &ValueExpr,
        line: usize,
    ) -> String {
        let mode_temp = self.next_temp();
        out.push_str("    int ");
        out.push_str(&mode_temp);
        out.push_str(" = ptn_declared_method_argument_by_ref(&runtime, ");
        out.push_str(receiver_temp);
        out.push_str(", \"");
        out.push_str(&c_string(method_name));
        out.push_str("\", ");
        out.push_str(&argument_index.to_string());
        out.push_str(");\n");

        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(";\n");

        out.push_str("    if (");
        out.push_str(&mode_temp);
        out.push_str(" == 1) {\n");
        let by_ref_temp = self.emit_by_ref_call_argument(
            out,
            argument,
            method_name,
            argument_index,
            "",
            line,
            true,
            true,
        );
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&by_ref_temp);
        out.push_str(";\n");

        out.push_str("    } else if (");
        out.push_str(&mode_temp);
        out.push_str(" == 0) {\n");
        let by_value_temp = self.emit_call_argument(out, method_name, argument_index, argument);
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&by_value_temp);
        out.push_str(";\n");

        out.push_str("    } else {\n");
        let dynamic_temp = self.emit_dynamic_call_argument(out, argument);
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&dynamic_temp);
        out.push_str(";\n");
        out.push_str("    }\n");

        result_temp
    }

    fn emit_runtime_dynamic_declared_method_call_argument(
        &mut self,
        out: &mut String,
        receiver_temp: &str,
        method_name_temp: &str,
        argument_index: usize,
        argument: &ValueExpr,
    ) -> String {
        let mode_temp = self.next_temp();
        out.push_str("    int ");
        out.push_str(&mode_temp);
        out.push_str(" = ptn_declared_method_argument_by_ref(&runtime, ");
        out.push_str(receiver_temp);
        out.push_str(", ");
        out.push_str(method_name_temp);
        out.push_str(", ");
        out.push_str(&argument_index.to_string());
        out.push_str(");\n");

        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(";\n");

        out.push_str("    if (");
        out.push_str(&mode_temp);
        out.push_str(" == 0) {\n");
        let by_value_temp =
            self.emit_call_argument(out, "dynamic method call", argument_index, argument);
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&by_value_temp);
        out.push_str(";\n");

        out.push_str("    } else {\n");
        let dynamic_temp = self.emit_dynamic_call_argument(out, argument);
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&dynamic_temp);
        out.push_str(";\n");
        out.push_str("    }\n");

        result_temp
    }

    fn emit_runtime_callable_call_argument(
        &mut self,
        out: &mut String,
        callee_temp: &str,
        argument_index: usize,
        argument: &ValueExpr,
        line: usize,
        disable_by_ref_argument_source: bool,
    ) -> String {
        if !value_needs_runtime_by_ref_argument_check(argument) {
            let temp = self.emit_dynamic_call_argument(out, argument);
            if disable_by_ref_argument_source {
                out.push_str("    ");
                out.push_str(&temp);
                out.push_str(" = ptn_value_disable_by_ref_argument_source(");
                out.push_str(&temp);
                out.push_str(");\n");
            }
            return temp;
        }

        let mode_temp = self.next_temp();
        out.push_str("    int ");
        out.push_str(&mode_temp);
        out.push_str(" = ptn_callable_argument_by_ref(&runtime, ");
        out.push_str(callee_temp);
        out.push_str(", ");
        out.push_str(&argument_index.to_string());
        out.push_str(");\n");

        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(";\n");

        out.push_str("    if (");
        out.push_str(&mode_temp);
        out.push_str(" == 1) {\n");
        if matches!(
            argument,
            ValueExpr::NullsafePropertyFetch { .. } | ValueExpr::PipeValue { .. }
        ) {
            out.push_str("        ");
            out.push_str(&result_temp);
            out.push_str(" = ptn_null();\n");
            let callable_name_temp = self.next_temp();
            out.push_str("        char *");
            out.push_str(&callable_name_temp);
            out.push_str(" = ptn_callable_output_name(");
            out.push_str(callee_temp);
            out.push_str(");\n");
            let parameter_fallback_temp = self.next_temp();
            out.push_str("        char ");
            out.push_str(&parameter_fallback_temp);
            out.push_str("[64];\n");
            let parameter_name_temp = self.next_temp();
            out.push_str("        const char *");
            out.push_str(&parameter_name_temp);
            out.push_str(" = ptn_callable_argument_parameter_name(&runtime, ");
            out.push_str(callee_temp);
            out.push_str(", ");
            out.push_str(&argument_index.to_string());
            out.push_str(", ");
            out.push_str(&parameter_fallback_temp);
            out.push_str(", sizeof(");
            out.push_str(&parameter_fallback_temp);
            out.push_str("));\n");
            out.push_str("        ptn_throw_by_reference_argument_error(&runtime, ");
            out.push_str(&callable_name_temp);
            out.push_str(", ");
            out.push_str(&(argument_index + 1).to_string());
            out.push_str(", ");
            out.push_str(&parameter_name_temp);
            out.push_str(", ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            out.push_str("        free(");
            out.push_str(&callable_name_temp);
            out.push_str(");\n");
        } else {
            let by_ref_temp = self.emit_by_ref_call_argument(
                out,
                argument,
                "{closure}",
                argument_index,
                "",
                line,
                true,
                true,
            );
            out.push_str("        ");
            out.push_str(&result_temp);
            if disable_by_ref_argument_source {
                out.push_str(" = ptn_value_disable_by_ref_argument_source(");
                out.push_str(&by_ref_temp);
                out.push_str(");\n");
            } else {
                out.push_str(" = ");
                out.push_str(&by_ref_temp);
                out.push_str(";\n");
            }
        }

        out.push_str("    } else if (");
        out.push_str(&mode_temp);
        out.push_str(" == 0) {\n");
        let by_value_temp = self.emit_call_argument(out, "{closure}", argument_index, argument);
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&by_value_temp);
        out.push_str(";\n");

        out.push_str("    } else {\n");
        let dynamic_temp = self.emit_dynamic_call_argument(out, argument);
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(&dynamic_temp);
        out.push_str(";\n");
        out.push_str("    }\n");

        result_temp
    }

    fn emit_runtime_callable_pipe_argument(
        &mut self,
        out: &mut String,
        callee_temp: &str,
        pipe_input_temp: &str,
        line: usize,
    ) -> String {
        let mode_temp = self.next_temp();
        out.push_str("    int ");
        out.push_str(&mode_temp);
        out.push_str(" = ptn_callable_argument_by_ref(&runtime, ");
        out.push_str(callee_temp);
        out.push_str(", 0);\n");

        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(";\n");
        out.push_str("    if (");
        out.push_str(&mode_temp);
        out.push_str(" == 1) {\n");
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_null();\n");
        let callable_name_temp = self.next_temp();
        out.push_str("        char *");
        out.push_str(&callable_name_temp);
        out.push_str(" = ptn_callable_output_name(");
        out.push_str(callee_temp);
        out.push_str(");\n");
        let parameter_fallback_temp = self.next_temp();
        out.push_str("        char ");
        out.push_str(&parameter_fallback_temp);
        out.push_str("[64];\n");
        let parameter_name_temp = self.next_temp();
        out.push_str("        const char *");
        out.push_str(&parameter_name_temp);
        out.push_str(" = ptn_callable_argument_parameter_name(&runtime, ");
        out.push_str(callee_temp);
        out.push_str(", 0, ");
        out.push_str(&parameter_fallback_temp);
        out.push_str(", sizeof(");
        out.push_str(&parameter_fallback_temp);
        out.push_str("));\n");
        out.push_str("        ptn_throw_by_reference_argument_error(&runtime, ");
        out.push_str(&callable_name_temp);
        out.push_str(", 1, ");
        out.push_str(&parameter_name_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        out.push_str("        free(");
        out.push_str(&callable_name_temp);
        out.push_str(");\n");
        out.push_str("    } else {\n");
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_value_share(");
        out.push_str(pipe_input_temp);
        out.push_str(");\n");
        out.push_str("    }\n");
        result_temp
    }

    fn emit_reference_source(
        &mut self,
        out: &mut String,
        source: &ValueExpr,
        line: usize,
    ) -> String {
        if let ValueExpr::StaticPropertyFetch {
            class_name,
            name,
            line,
        } = source
        {
            return self.emit_static_property_reference(out, class_name, name, *line);
        }

        if let Some(target) = reference_target_from_value(source) {
            return self.emit_reference_target(out, &target);
        }

        let result_temp = self.emit_reference_candidate_value(out, source);
        let temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&temp);
        out.push_str(" = ptn_reference_source_or_value(&runtime, ");
        out.push_str(&result_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        emit_value_cleanup(out, "    ", &result_temp);
        temp
    }

    fn emit_yield(
        &mut self,
        out: &mut String,
        key: Option<&ValueExpr>,
        value: Option<&ValueExpr>,
        line: usize,
    ) -> String {
        let key_is_direct_yield = key.map(value_expr_is_direct_yield).unwrap_or(false);
        let value_is_direct_yield = value.map(value_expr_is_direct_yield).unwrap_or(false);
        let key_temp = key.map(|key| self.emit_materialized_value(out, key));
        let value_temp = match value {
            Some(value) if self.current_function_return_by_ref => {
                if let ValueExpr::StaticPropertyFetch {
                    class_name,
                    name,
                    line,
                } = value
                {
                    self.emit_static_property_reference(out, class_name, name, *line)
                } else if let Some(target) = reference_target_from_value(value) {
                    self.emit_reference_target(out, &target)
                } else {
                    self.emit_raw_materialized_value(out, value)
                }
            }
            Some(value) => self.emit_materialized_value(out, value),
            None => {
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_null();\n");
                temp
            }
        };
        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_generator_yield(&runtime, ");
        out.push_str(if key_temp.is_some() { "1" } else { "0" });
        out.push_str(", ");
        out.push_str(key_temp.as_deref().unwrap_or("ptn_null()"));
        out.push_str(", ");
        out.push_str(if value.is_some() { "1" } else { "0" });
        out.push_str(", ");
        out.push_str(&value_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        if key_is_direct_yield {
            let source_back_offset = if value_is_direct_yield { 2 } else { 1 };
            out.push_str("    ptn_generator_register_send_yield_slot(&runtime, ");
            out.push_str(&source_back_offset.to_string());
            out.push_str(", 1, ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
        }
        if value_is_direct_yield {
            out.push_str("    ptn_generator_register_send_yield_slot(&runtime, 1, 0, ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
        }
        if let Some(key_temp) = key_temp {
            emit_value_cleanup(out, "    ", &key_temp);
        }
        emit_value_cleanup(out, "    ", &value_temp);
        if !self.generator_throw_catch_stack.is_empty() {
            let registrations: Vec<_> = self
                .generator_throw_catch_stack
                .iter()
                .rev()
                .flat_map(|registrations| registrations.iter().cloned())
                .collect();
            for registration in registrations {
                out.push_str("    ptn_generator_register_throw_catch(&runtime, ");
                out.push_str(&registration.handler_id.to_string());
                out.push_str(");\n");
            }
        }
        result_temp
    }

    fn emit_yield_from(&mut self, out: &mut String, expr: &ValueExpr, line: usize) -> String {
        if matches!(expr, ValueExpr::Yield { .. }) {
            let source_temp = self.emit_materialized_value(out, expr);
            emit_value_cleanup(out, "    ", &source_temp);
            out.push_str("    ptn_generator_register_send_yield_from(&runtime, ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            let result_temp = self.next_temp();
            out.push_str("    PtnValue ");
            out.push_str(&result_temp);
            out.push_str(" = ptn_null();\n");
            return result_temp;
        }

        let pending_yield_from_parent = if self.value_is_anonymous_generator_closure_call(expr) {
            let previous_generator_temp = self.next_temp();
            let previous_line_temp = self.next_temp();
            out.push_str("    PtnGenerator *");
            out.push_str(&previous_generator_temp);
            out.push_str(" = runtime.pending_yield_from_generator;\n");
            out.push_str("    size_t ");
            out.push_str(&previous_line_temp);
            out.push_str(" = runtime.pending_yield_from_line;\n");
            out.push_str("    runtime.pending_yield_from_generator = runtime.current_generator;\n");
            out.push_str("    runtime.pending_yield_from_line = ");
            out.push_str(&line.to_string());
            out.push_str(";\n");
            Some((previous_generator_temp, previous_line_temp))
        } else {
            None
        };
        let source_temp = self.emit_materialized_value(out, expr);
        if let Some((previous_generator_temp, previous_line_temp)) = pending_yield_from_parent {
            out.push_str("    runtime.pending_yield_from_generator = ");
            out.push_str(&previous_generator_temp);
            out.push_str(";\n");
            out.push_str("    runtime.pending_yield_from_line = ");
            out.push_str(&previous_line_temp);
            out.push_str(";\n");
        }
        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_generator_yield_from(&runtime, ");
        out.push_str(&source_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        emit_value_cleanup(out, "    ", &source_temp);
        if !self.generator_throw_catch_stack.is_empty() {
            let registrations: Vec<_> = self
                .generator_throw_catch_stack
                .iter()
                .rev()
                .flat_map(|registrations| registrations.iter().cloned())
                .collect();
            for registration in registrations {
                out.push_str("    ptn_generator_register_throw_catch(&runtime, ");
                out.push_str(&registration.handler_id.to_string());
                out.push_str(");\n");
            }
        }
        result_temp
    }

    fn emit_reference_target(&mut self, out: &mut String, target: &ReferenceTarget) -> String {
        match target {
            ReferenceTarget::Variable { name, line } => {
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_null();\n");
                if name == "GLOBALS" {
                    self.emit_globals_reference_fatal(
                        out,
                        "Cannot acquire reference to $GLOBALS",
                        *line,
                    );
                } else {
                    out.push_str("    ");
                    out.push_str(&temp);
                    out.push_str(" = ptn_runtime_reference_for_variable(&runtime, \"");
                    out.push_str(&c_string(name));
                    out.push_str("\");\n");
                }
                temp
            }
            ReferenceTarget::DynamicVariable { name, line } => {
                let (name_temp, len_temp) =
                    self.emit_dynamic_variable_name_with_len(out, name, *line);
                self.emit_dynamic_this_reassignment_guard(out, &name_temp, *line);
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_runtime_reference_for_variable_len(&runtime, ");
                out.push_str(&name_temp);
                out.push_str(", ");
                out.push_str(&len_temp);
                out.push_str(");\n");
                out.push_str("    free(");
                out.push_str(&name_temp);
                out.push_str(");\n");
                temp
            }
            ReferenceTarget::ArrayDim(target) => {
                let path = emit_array_path_segments(out, self, &target.dimensions);
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_runtime_reference_for_array_path(&runtime, \"");
                out.push_str(&c_string(&target.array));
                out.push_str("\", ");
                out.push_str(&path.name);
                out.push_str(", ");
                out.push_str(&path.len.to_string());
                out.push_str(", ");
                out.push('"');
                out.push_str(&c_string(&self.source_file));
                out.push_str("\", ");
                out.push_str(&target.line.to_string());
                out.push_str(");\n");
                for segment_temp in path.value_temps {
                    emit_value_cleanup(out, "    ", &segment_temp);
                }
                temp
            }
            ReferenceTarget::PropertyArrayDim {
                receiver,
                name,
                dimensions,
                line,
            } => {
                let receiver_temp = self.emit_materialized_value(out, receiver);
                let property_reference_temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&property_reference_temp);
                out.push_str(" = ptn_object_reference_for_property(&runtime, ");
                out.push_str(&receiver_temp);
                out.push_str(", \"");
                out.push_str(&c_string(name));
                out.push_str("\", ");
                self.emit_access_scope(out);
                out.push_str(", ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                let path = emit_array_path_segments(out, self, dimensions);
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_value_reference_for_array_path(&runtime, &");
                out.push_str(&property_reference_temp);
                out.push_str(", ");
                out.push_str(&path.name);
                out.push_str(", ");
                out.push_str(&path.len.to_string());
                out.push_str(", ");
                out.push('"');
                out.push_str(&c_string(&self.source_file));
                out.push_str("\", ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                for segment_temp in path.value_temps {
                    emit_value_cleanup(out, "    ", &segment_temp);
                }
                emit_value_cleanup(out, "    ", &property_reference_temp);
                emit_value_cleanup(out, "    ", &receiver_temp);
                temp
            }
            ReferenceTarget::Property {
                receiver,
                name,
                line,
            } => {
                let receiver_temp = self.emit_materialized_value(out, receiver);
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_object_reference_for_property(&runtime, ");
                out.push_str(&receiver_temp);
                out.push_str(", \"");
                out.push_str(&c_string(name));
                out.push_str("\", ");
                self.emit_access_scope(out);
                out.push_str(", ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                emit_value_cleanup(out, "    ", &receiver_temp);
                temp
            }
            ReferenceTarget::DynamicProperty {
                receiver,
                name,
                line,
            } => {
                let receiver_temp = self.emit_materialized_value(out, receiver);
                let name_temp = self.emit_dynamic_property_name(out, name, *line);
                let temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&temp);
                out.push_str(" = ptn_object_reference_for_property(&runtime, ");
                out.push_str(&receiver_temp);
                out.push_str(", ");
                out.push_str(&name_temp);
                out.push_str(", ");
                self.emit_access_scope(out);
                out.push_str(", ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                out.push_str("    free(");
                out.push_str(&name_temp);
                out.push_str(");\n");
                emit_value_cleanup(out, "    ", &receiver_temp);
                temp
            }
        }
    }

    fn emit_call_arguments_builder(
        &mut self,
        out: &mut String,
        function_name: &str,
        arguments: &[ValueExpr],
        argument_names: &[Option<String>],
        argument_unpacks: &[bool],
        line: usize,
        dynamic_argument_materialization: bool,
        by_ref_parameters: Option<&[FunctionParameter]>,
    ) -> String {
        let by_ref_unpack_modes = by_ref_parameters.and_then(by_ref_unpack_parameter_modes);
        let args_temp = self.next_temp();
        out.push_str("    PtnCallArguments ");
        out.push_str(&args_temp);
        out.push_str(";\n");
        out.push_str("    ptn_call_arguments_init(&");
        out.push_str(&args_temp);
        out.push_str(");\n");
        for (argument_index, argument) in arguments.iter().enumerate() {
            if argument_unpacks
                .get(argument_index)
                .copied()
                .unwrap_or(false)
            {
                if let Some((by_ref_indices, by_ref_variadic_index)) = by_ref_unpack_modes.as_ref()
                {
                    let by_ref_parameter_names: Vec<&str> = by_ref_parameters
                        .unwrap_or(&[])
                        .iter()
                        .enumerate()
                        .filter(|(_, parameter)| parameter.by_ref && !parameter.is_variadic)
                        .map(|(_, parameter)| parameter.name.as_str())
                        .collect();
                    let indices_temp = if by_ref_indices.is_empty() {
                        None
                    } else {
                        let temp = self.next_temp();
                        out.push_str("    const size_t ");
                        out.push_str(&temp);
                        out.push_str("[] = { ");
                        for (index, parameter_index) in by_ref_indices.iter().enumerate() {
                            if index > 0 {
                                out.push_str(", ");
                            }
                            out.push_str(&parameter_index.to_string());
                        }
                        out.push_str(" };\n");
                        Some(temp)
                    };
                    let indices_expr = indices_temp.as_deref().unwrap_or("NULL");
                    let names_temp = if by_ref_parameter_names.is_empty() {
                        None
                    } else {
                        let temp = self.next_temp();
                        out.push_str("    const char *");
                        out.push_str(&temp);
                        out.push_str("[] = { ");
                        for (index, parameter_name) in by_ref_parameter_names.iter().enumerate() {
                            if index > 0 {
                                out.push_str(", ");
                            }
                            out.push('"');
                            out.push_str(&c_string(parameter_name));
                            out.push('"');
                        }
                        out.push_str(" };\n");
                        Some(temp)
                    };
                    let names_expr = names_temp.as_deref().unwrap_or("NULL");
                    let variadic_flag = if by_ref_variadic_index.is_some() {
                        "1"
                    } else {
                        "0"
                    };
                    let variadic_index = by_ref_variadic_index.unwrap_or(0);
                    if let ValueExpr::Load { name, .. } = argument {
                        out.push_str("    ptn_call_arguments_unpack_variable_with_parameter_modes(&runtime, &");
                        out.push_str(&args_temp);
                        out.push_str(", \"");
                        out.push_str(&c_string(name));
                        out.push_str("\", ");
                        out.push_str(indices_expr);
                        out.push_str(", ");
                        out.push_str(names_expr);
                        out.push_str(", ");
                        out.push_str(&by_ref_indices.len().to_string());
                        out.push_str(", ");
                        out.push_str(variadic_flag);
                        out.push_str(", ");
                        out.push_str(&variadic_index.to_string());
                        out.push_str(", ");
                        out.push('"');
                        out.push_str(&c_string(function_name));
                        out.push_str("\", ");
                        out.push_str(&line.to_string());
                        out.push_str(");\n");
                    } else {
                        let value_temp = self.emit_materialized_value(out, argument);
                        out.push_str(
                            "    ptn_call_arguments_unpack_value_with_parameter_modes(&runtime, &",
                        );
                        out.push_str(&args_temp);
                        out.push_str(", &");
                        out.push_str(&value_temp);
                        out.push_str(", ");
                        out.push_str(indices_expr);
                        out.push_str(", ");
                        out.push_str(names_expr);
                        out.push_str(", ");
                        out.push_str(&by_ref_indices.len().to_string());
                        out.push_str(", ");
                        out.push_str(variadic_flag);
                        out.push_str(", ");
                        out.push_str(&variadic_index.to_string());
                        out.push_str(", ");
                        out.push('"');
                        out.push_str(&c_string(function_name));
                        out.push_str("\", ");
                        out.push_str(&line.to_string());
                        out.push_str(");\n");
                        emit_value_cleanup(out, "    ", &value_temp);
                    }
                } else {
                    let value_temp = self.emit_reference_candidate_value(out, argument);
                    out.push_str("    ptn_call_arguments_unpack(&runtime, &");
                    out.push_str(&args_temp);
                    out.push_str(", ");
                    out.push_str(&value_temp);
                    out.push_str(", ");
                    out.push_str(&line.to_string());
                    out.push_str(");\n");
                    emit_value_cleanup(out, "    ", &value_temp);
                }
            } else {
                let by_ref_parameter = by_ref_parameters.and_then(|parameters| {
                    by_ref_parameter_for_argument(parameters, argument_index)
                });
                let value_temp = if let Some(parameter) = by_ref_parameter {
                    let parameter_name = if parameter.is_variadic {
                        ""
                    } else {
                        &parameter.name
                    };
                    self.emit_by_ref_call_argument(
                        out,
                        argument,
                        function_name,
                        argument_index,
                        parameter_name,
                        line,
                        true,
                        true,
                    )
                } else if dynamic_argument_materialization {
                    self.emit_dynamic_call_argument(out, argument)
                } else {
                    self.emit_call_argument(out, function_name, argument_index, argument)
                };
                out.push_str("    ptn_call_arguments_append_checked_owned(&runtime, &");
                out.push_str(&args_temp);
                out.push_str(", ");
                if let Some(Some(argument_name)) = argument_names.get(argument_index) {
                    out.push('"');
                    out.push_str(&c_string(argument_name));
                    out.push('"');
                } else {
                    out.push_str("NULL");
                }
                out.push_str(", ptn_value_share(");
                out.push_str(&value_temp);
                out.push_str("), ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                emit_value_cleanup(out, "    ", &value_temp);
            }
        }
        args_temp
    }

    fn emit_discarded_array_splice_call(
        &mut self,
        out: &mut String,
        arguments: &[ValueExpr],
        line: usize,
    ) -> String {
        let mut temps = Vec::with_capacity(arguments.len());
        for (argument_index, argument) in arguments.iter().enumerate() {
            if argument_index == 0 {
                temps.push(self.emit_by_ref_call_argument(
                    out,
                    argument,
                    "array_splice",
                    argument_index,
                    "array",
                    line,
                    true,
                    true,
                ));
            } else {
                temps.push(self.emit_call_argument(out, "array_splice", argument_index, argument));
            }
        }

        let args_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&args_temp);
        out.push_str("[] = { ");
        for (index, temp) in temps.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str("ptn_value_share(");
            out.push_str(temp);
            out.push(')');
        }
        out.push_str(" };\n");

        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_call_function(&runtime, \"array_splice\", ");
        out.push_str(&arguments.len().to_string());
        out.push_str(", ");
        out.push_str(&args_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        out.push_str("    ptn_runtime_array_splice_discard_result(&runtime, ");
        out.push_str(&args_temp);
        out.push_str("[0], &");
        out.push_str(&result_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        for index in 0..temps.len() {
            emit_value_cleanup(out, "    ", &format!("{args_temp}[{index}]"));
        }
        for temp in temps {
            emit_value_cleanup(out, "    ", &temp);
        }
        result_temp
    }

    fn emit_direct_var_dump_call(
        &mut self,
        out: &mut String,
        result_temp: &str,
        arguments: &[ValueExpr],
        argument_unpacks: &[bool],
        line: usize,
    ) -> String {
        if argument_unpacks.iter().any(|unpack| *unpack) {
            let args_temp = self.emit_call_arguments_builder(
                out,
                "var_dump",
                arguments,
                &[],
                argument_unpacks,
                line,
                false,
                None,
            );
            out.push_str("    PtnValue ");
            out.push_str(result_temp);
            out.push_str(" = ptn_direct_var_dump(&runtime, ");
            out.push_str(&args_temp);
            out.push_str(".len, ");
            out.push_str(&args_temp);
            out.push_str(".values, ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            out.push_str("    ptn_call_arguments_destroy(&");
            out.push_str(&args_temp);
            out.push_str(");\n");
            return result_temp.to_string();
        }

        if arguments.is_empty() {
            out.push_str("    PtnValue ");
            out.push_str(result_temp);
            out.push_str(" = ptn_direct_var_dump(&runtime, 0, NULL, ");
            out.push_str(&line.to_string());
            out.push_str(");\n");
            return result_temp.to_string();
        }

        let mut temps = Vec::with_capacity(arguments.len());
        for (argument_index, argument) in arguments.iter().enumerate() {
            temps.push(self.emit_call_argument(out, "var_dump", argument_index, argument));
        }
        let args_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&args_temp);
        out.push_str("[] = { ");
        for (index, temp) in temps.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str("ptn_value_share(");
            out.push_str(temp);
            out.push(')');
        }
        out.push_str(" };\n");
        out.push_str("    PtnValue ");
        out.push_str(result_temp);
        out.push_str(" = ptn_direct_var_dump(&runtime, ");
        out.push_str(&arguments.len().to_string());
        out.push_str(", ");
        out.push_str(&args_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        for index in 0..temps.len() {
            emit_value_cleanup(out, "    ", &format!("{args_temp}[{index}]"));
        }
        for temp in temps {
            emit_value_cleanup(out, "    ", &temp);
        }
        result_temp.to_string()
    }

    fn emit_direct_implode_call(
        &mut self,
        out: &mut String,
        name: &str,
        arguments: &[ValueExpr],
        line: usize,
    ) -> String {
        let mut temps = Vec::with_capacity(arguments.len());
        for (argument_index, argument) in arguments.iter().enumerate() {
            temps.push(self.emit_call_argument(out, name, argument_index, argument));
        }
        let args_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&args_temp);
        out.push_str("[] = { ");
        for (index, temp) in temps.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str("ptn_value_share(");
            out.push_str(temp);
            out.push(')');
        }
        out.push_str(" };\n");

        let result_temp = self.next_temp();
        let helper = if name.eq_ignore_ascii_case("join") {
            "ptn_direct_join"
        } else {
            "ptn_direct_implode"
        };
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(helper);
        out.push_str("(&runtime, ");
        out.push_str(&arguments.len().to_string());
        out.push_str(", ");
        out.push_str(&args_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        for index in 0..temps.len() {
            emit_value_cleanup(out, "    ", &format!("{args_temp}[{index}]"));
        }
        for temp in temps {
            emit_value_cleanup(out, "    ", &temp);
        }
        result_temp
    }

    fn emit_direct_preg_match_call(
        &mut self,
        out: &mut String,
        arguments: &[ValueExpr],
        line: usize,
    ) -> String {
        if let [pattern, subject, ValueExpr::Load {
            name: matches_name, ..
        }, ValueExpr::Int(0), offset] = arguments
        {
            if self.preg_match_pattern_is_direct_word_boundary(pattern) && matches_name != "GLOBALS"
            {
                let subject_temp = self.emit_call_argument(out, "preg_match", 1, subject);
                let offset_temp = self.emit_call_argument(out, "preg_match", 4, offset);
                let result_temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&result_temp);
                out.push_str(" = ptn_direct_preg_match_word_boundary_variable_matches(&runtime, ");
                out.push_str(&subject_temp);
                out.push_str(", \"");
                out.push_str(&c_string(matches_name));
                out.push_str("\", ");
                out.push_str(&offset_temp);
                out.push_str(", ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                emit_value_cleanup(out, "    ", &subject_temp);
                emit_value_cleanup(out, "    ", &offset_temp);
                return result_temp;
            }
            if matches!(pattern, ValueExpr::String(pattern) if pattern == "/\\G\\w/u")
                && matches_name != "GLOBALS"
            {
                let subject_temp = self.emit_call_argument(out, "preg_match", 1, subject);
                let offset_temp = self.emit_call_argument(out, "preg_match", 4, offset);
                let result_temp = self.next_temp();
                out.push_str("    PtnValue ");
                out.push_str(&result_temp);
                out.push_str(
                    " = ptn_direct_preg_match_contiguous_word_variable_matches(&runtime, ",
                );
                out.push_str(&subject_temp);
                out.push_str(", \"");
                out.push_str(&c_string(matches_name));
                out.push_str("\", ");
                out.push_str(&offset_temp);
                out.push_str(", ");
                out.push_str(&line.to_string());
                out.push_str(");\n");
                emit_value_cleanup(out, "    ", &subject_temp);
                emit_value_cleanup(out, "    ", &offset_temp);
                return result_temp;
            }
        }

        let mut temps = Vec::with_capacity(arguments.len());
        for (argument_index, argument) in arguments.iter().enumerate() {
            if argument_index == 2 {
                temps.push(self.emit_by_ref_call_argument(
                    out,
                    argument,
                    "preg_match",
                    argument_index,
                    "matches",
                    line,
                    true,
                    true,
                ));
            } else {
                temps.push(self.emit_call_argument(out, "preg_match", argument_index, argument));
            }
        }

        let args_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&args_temp);
        out.push_str("[] = { ");
        for (index, temp) in temps.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str("ptn_value_share(");
            out.push_str(temp);
            out.push(')');
        }
        out.push_str(" };\n");

        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_internal_preg_match(&runtime, ");
        out.push_str(&arguments.len().to_string());
        out.push_str(", ");
        out.push_str(&args_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        for index in 0..temps.len() {
            emit_value_cleanup(out, "    ", &format!("{args_temp}[{index}]"));
        }
        for temp in temps {
            emit_value_cleanup(out, "    ", &temp);
        }
        result_temp
    }

    fn emit_direct_pcre_call(
        &mut self,
        out: &mut String,
        name: &str,
        arguments: &[ValueExpr],
        by_ref_argument: Option<(usize, &str)>,
        line: usize,
    ) -> String {
        let mut temps = Vec::with_capacity(arguments.len());
        for (argument_index, argument) in arguments.iter().enumerate() {
            if let Some((by_ref_index, parameter_name)) = by_ref_argument {
                if argument_index == by_ref_index {
                    temps.push(self.emit_by_ref_call_argument(
                        out,
                        argument,
                        name,
                        argument_index,
                        parameter_name,
                        line,
                        true,
                        true,
                    ));
                    continue;
                }
            }
            temps.push(self.emit_call_argument(out, name, argument_index, argument));
        }

        let args_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&args_temp);
        out.push_str("[] = { ");
        for (index, temp) in temps.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str("ptn_value_share(");
            out.push_str(temp);
            out.push(')');
        }
        out.push_str(" };\n");

        let helper = if name.eq_ignore_ascii_case("preg_match_all") {
            "ptn_internal_preg_match_all"
        } else {
            "ptn_internal_preg_split"
        };
        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ");
        out.push_str(helper);
        out.push_str("(&runtime, ");
        out.push_str(&arguments.len().to_string());
        out.push_str(", ");
        out.push_str(&args_temp);
        out.push_str(", ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        for index in 0..temps.len() {
            emit_value_cleanup(out, "    ", &format!("{args_temp}[{index}]"));
        }
        for temp in temps {
            emit_value_cleanup(out, "    ", &temp);
        }
        result_temp
    }

