    fn emit_direct_call_user_func_call(
        &mut self,
        out: &mut String,
        arguments: &[ValueExpr],
        line: usize,
        discarded: bool,
    ) -> String {
        let result_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_null();\n");
        out.push_str("    if (ptn_runtime_function_disabled(&runtime, \"call_user_func\")) {\n");
        out.push_str("        ");
        out.push_str(&result_temp);
        out.push_str(" = ptn_call_internal(&runtime, \"call_user_func\", 0, NULL, ");
        out.push_str(&line.to_string());
        out.push_str(");\n");
        out.push_str("    } else {\n");
        let callable_temp = self.emit_materialized_value(out, &arguments[0]);
        let previous_call_site_line_temp = self.next_temp();
        let previous_warn_by_ref_temp = self.next_temp();
        let checked_callback_temp = self.next_temp();
        let trace_frame_temp = self.next_temp();
        let callback_ok_temp = self.next_temp();
        out.push_str("    size_t ");
        out.push_str(&previous_call_site_line_temp);
        out.push_str(" = runtime.call_site_line;\n");
        out.push_str("    int ");
        out.push_str(&previous_warn_by_ref_temp);
        out.push_str(" = runtime.warn_by_ref_argument_mismatch;\n");
        out.push_str("    runtime.call_site_line = ");
        out.push_str(&line.to_string());
        out.push_str(";\n");
        out.push_str("    runtime.warn_by_ref_argument_mismatch = 1;\n");
        out.push_str("    PtnValue ");
        out.push_str(&checked_callback_temp);
        out.push_str(" = ptn_internal_expect_callback_arg_autoload_chaining_deprecation(&runtime, \"call_user_func\", 1, \"callback\", ptn_value_share(");
        out.push_str(&callable_temp);
        out.push_str("));\n");
        out.push_str("    int ");
        out.push_str(&callback_ok_temp);
        out.push_str(" = 1;\n");
        out.push_str("    if (runtime.exceptions->active_exception == NULL) {\n");
        if arguments.len() == 1 {
            if discarded {
                self.emit_no_discard_warning_for_callable_temp(out, &checked_callback_temp, line);
            }
            out.push_str("    PtnTraceFrame ");
            out.push_str(&trace_frame_temp);
            out.push_str(";\n");
            out.push_str("    ptn_runtime_push_trace_frame(&runtime, &");
            out.push_str(&trace_frame_temp);
            out.push_str(", \"call_user_func\", ptn_runtime_internal_trace_file(&runtime, ");
            out.push_str(&line.to_string());
            out.push_str("), ");
            out.push_str(&line.to_string());
            out.push_str(", 1, &");
            out.push_str(&callable_temp);
            out.push_str(");\n");
            out.push_str(&callback_ok_temp);
            out.push_str(" = ptn_internal_call_callback_capturing_exception_impl(&runtime, ");
            out.push_str(&checked_callback_temp);
            out.push_str(", 0, NULL, NULL, ");
            out.push_str(&line.to_string());
            out.push_str(", 1, 0, &");
            out.push_str(&result_temp);
            out.push_str(");\n");
            out.push_str("    ptn_runtime_pop_trace_frame(&runtime, &");
            out.push_str(&trace_frame_temp);
            out.push_str(");\n");
            out.push_str("    }\n");
            out.push_str("    runtime.warn_by_ref_argument_mismatch = ");
            out.push_str(&previous_warn_by_ref_temp);
            out.push_str(";\n");
            out.push_str("    runtime.call_site_line = ");
            out.push_str(&previous_call_site_line_temp);
            out.push_str(";\n");
            emit_value_cleanup(out, "    ", &checked_callback_temp);
            emit_value_cleanup(out, "    ", &callable_temp);
            out.push_str("    if (!");
            out.push_str(&callback_ok_temp);
            out.push_str(") {\n");
            out.push_str("        ptn_rethrow_exception(&runtime);\n");
            out.push_str("    }\n");
            out.push_str("    }\n");
            return result_temp;
        }

        let mut temps = Vec::with_capacity(arguments.len() - 1);
        for (argument_index, argument) in arguments.iter().enumerate().skip(1) {
            let temp = self.emit_call_argument(out, "call_user_func", argument_index, argument);
            out.push_str("    ");
            out.push_str(&temp);
            out.push_str(" = ptn_value_disable_by_ref_argument_source(");
            out.push_str(&temp);
            out.push_str(");\n");
            temps.push(temp);
        }

        let args_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&args_temp);
        out.push_str("[] = { ");
        for (index, temp) in temps.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str("ptn_value_share(");
            out.push_str(temp);
            out.push(')');
        }
        out.push_str(" };\n");
        emit_push_owned_call_argument_roots(out, "    ", &args_temp, temps.len());
        if discarded {
            self.emit_no_discard_warning_for_callable_temp(out, &checked_callback_temp, line);
        }
        let trace_args_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&trace_args_temp);
        out.push_str("[] = { ");
        out.push_str(&callable_temp);
        for index in 0..temps.len() {
            out.push_str(", ");
            out.push_str(&args_temp);
            out.push('[');
            out.push_str(&index.to_string());
            out.push(']');
        }
        out.push_str(" };\n");
        out.push_str("    PtnTraceFrame ");
        out.push_str(&trace_frame_temp);
        out.push_str(";\n");
        out.push_str("    ptn_runtime_push_trace_frame(&runtime, &");
        out.push_str(&trace_frame_temp);
        out.push_str(", \"call_user_func\", ptn_runtime_internal_trace_file(&runtime, ");
        out.push_str(&line.to_string());
        out.push_str("), ");
        out.push_str(&line.to_string());
        out.push_str(", ");
        out.push_str(&arguments.len().to_string());
        out.push_str(", ");
        out.push_str(&trace_args_temp);
        out.push_str(");\n");
        out.push_str(&callback_ok_temp);
        out.push_str(" = ptn_internal_call_callback_capturing_exception_impl(&runtime, ");
        out.push_str(&checked_callback_temp);
        out.push_str(", ");
        out.push_str(&temps.len().to_string());
        out.push_str(", ");
        out.push_str(&args_temp);
        out.push_str(", NULL, ");
        out.push_str(&line.to_string());
        out.push_str(", 1, 0, &");
        out.push_str(&result_temp);
        out.push_str(");\n");
        out.push_str("    ptn_runtime_pop_trace_frame(&runtime, &");
        out.push_str(&trace_frame_temp);
        out.push_str(");\n");
        emit_pop_owned_call_argument_roots(out, "    ", temps.len());
        for index in 0..temps.len() {
            emit_value_cleanup(out, "    ", &format!("{args_temp}[{index}]"));
        }
        for temp in temps {
            emit_value_cleanup(out, "    ", &temp);
        }
        out.push_str("    }\n");
        out.push_str("    runtime.warn_by_ref_argument_mismatch = ");
        out.push_str(&previous_warn_by_ref_temp);
        out.push_str(";\n");
        out.push_str("    runtime.call_site_line = ");
        out.push_str(&previous_call_site_line_temp);
        out.push_str(";\n");
        emit_value_cleanup(out, "    ", &checked_callback_temp);
        emit_value_cleanup(out, "    ", &callable_temp);
        out.push_str("    if (!");
        out.push_str(&callback_ok_temp);
        out.push_str(") {\n");
        out.push_str("        ptn_rethrow_exception(&runtime);\n");
        out.push_str("    }\n");
        out.push_str("    }\n");
        result_temp
    }

